  insert into public.lessons (curriculum_version_id, grade_subject_id, topic_id, title, description, estimated_minutes, difficulty, language, teacher_notes, learner_instructions, sort_order, accessibility) values (v_version, v_gs, pg_temp.pkid('topic:WN'), $t$Counting in steps up to 10 000$t$, $t$Learners count forwards and backwards in 2s, 3s, 5s, 10s, 25s, 50s and 100s with numbers between 0 and at least 10 000.$t$, 40, 'standard', 'en', $t$Everything can be done with the chalkboard, bottle tops and the learners' own voices. Start with small numbers and move on only when learners are secure. Examples are Funda360 examples, not DBE examples. This is a draft that a curriculum specialist has not yet checked.$t$, $t$Count aloud with your class and your group, then write the missing numbers in each pattern.$t$, 1, $j${"reading_level":"Grade 4","offline_ready":true,"low_resource":true}$j$::jsonb) returning id into v_id;
