  insert into public.lessons (curriculum_version_id, grade_subject_id, topic_id, title, description, estimated_minutes, difficulty, language, teacher_notes, learner_instructions, sort_order, accessibility) values (v_version, v_gs, pg_temp.pkid('topic:WN'), $t$Place value and representing four-digit numbers$t$, $t$Learners say what each digit in a four-digit number is worth and show the same number in several ways.$t$, 45, 'standard', 'en', $t$Learners need to see that the same number can be shown as digits, words, expanded form, a chart, bundles or a spot on a number line. Draw the chart on the board; no projector is needed. Examples are Funda360 examples, not DBE examples. This is a draft that a curriculum specialist has not yet checked.$t$, $t$Build the number, say it, write it in words and in expanded form.$t$, 2, $j${"reading_level":"Grade 4","offline_ready":true,"low_resource":true}$j$::jsonb) returning id into v_id;
