  insert into public.lessons (curriculum_version_id, grade_subject_id, topic_id, title, description, estimated_minutes, difficulty, language, teacher_notes, learner_instructions, sort_order, accessibility) values (v_version, v_gs, pg_temp.pkid('topic:WN'), $t$Ordering and comparing whole numbers$t$, $t$Learners compare four-digit numbers digit by digit, use <, > and =, and put numbers in order.$t$, 40, 'standard', 'en', $t$Always compare the biggest place first. Learners often compare the last digits by mistake, so ask them to say which place decided. Examples are Funda360 examples, not DBE examples. This is a draft that a curriculum specialist has not yet checked.$t$, $t$Compare from the left, say which place decides, then write the symbol.$t$, 3, $j${"reading_level":"Grade 4","offline_ready":true,"low_resource":true}$j$::jsonb) returning id into v_id;
