  insert into public.lessons (curriculum_version_id, grade_subject_id, topic_id, title, description, estimated_minutes, difficulty, language, teacher_notes, learner_instructions, sort_order, accessibility) values (v_version, v_gs, pg_temp.pkid('topic:WN'), $t$Odd and even numbers to 1 000$t$, $t$Learners decide whether a number up to 1 000 is odd or even by looking at the ones digit.$t$, 30, 'standard', 'en', $t$Link to pairing: an even number can be shared into pairs with none left over. Examples are Funda360 examples, not DBE examples. This is a draft that a curriculum specialist has not yet checked.$t$, $t$Make pairs, look at the last digit, and say odd or even.$t$, 4, $j${"reading_level":"Grade 4","offline_ready":true,"low_resource":true}$j$::jsonb) returning id into v_id;
