  insert into public.learning_activities (lesson_id, curriculum_version_id, title, instructions, activity_type, grouping, difficulty, estimated_minutes, resource_id, sort_order) values (pg_temp.pkid('lesson:L04'), v_version, $t$Stand up, sit down$t$, $t$Listen to the number. Stand if it is even, sit if it is odd.$t$, $t$game$t$, $t$whole_class$t$, $t$standard$t$, 10, pg_temp.pkid($t$res:L04:Stand up, sit down$t$), 1);
  insert into public.learning_activities (lesson_id, curriculum_version_id, title, instructions, activity_type, grouping, difficulty, estimated_minutes, resource_id, sort_order) values (pg_temp.pkid('lesson:L04'), v_version, $t$Practice set$t$, $t$Complete the practice set on your own.$t$, $t$individual_practice$t$, $t$individual$t$, $t$standard$t$, 10, pg_temp.pkid($t$res:L04:Practice set: odd or even$t$), 2);
  insert into public.lessons (curriculum_version_id, grade_subject_id, topic_id, title, description, estimated_minutes, difficulty, language, teacher_notes, learner_instructions, sort_order, accessibility) values (v_version, v_gs, pg_temp.pkid('topic:WN'), $t$Rounding to the nearest 10, 100 and 1 000$t$, $t$Learners round four-digit numbers by looking at the digit to the right of the place they are rounding to.$t$, 45, 'standard', 'en', $t$Learners round to the nearest 10 by looking at the ones digit, to the nearest 100 by the tens digit and to the nearest 1 000 by the hundreds digit. Numbers exactly halfway round up. Rounding is done once from the original number. Examples are Funda360 examples, not DBE examples. This is a draft that a curriculum specialist has not yet checked.$t$, $t$Find the rounding digit, then decide whether the number goes up or stays.$t$, 5, $j${"reading_level":"Grade 4","offline_ready":true,"low_resource":true}$j$::jsonb) returning id into v_id;
