  insert into public.learning_activities (lesson_id, curriculum_version_id, title, instructions, activity_type, grouping, difficulty, estimated_minutes, resource_id, sort_order) values (pg_temp.pkid('lesson:L05'), v_version, $t$Walk to the nearest hundred$t$, $t$Listen to the number, then walk to the hundred it is nearest to.$t$, $t$game$t$, $t$whole_class$t$, $t$standard$t$, 15, pg_temp.pkid($t$res:L05:Walk to the nearest hundred$t$), 1);
