  insert into public.lessons (curriculum_version_id, grade_subject_id, topic_id, title, description, estimated_minutes, difficulty, language, teacher_notes, learner_instructions, sort_order, accessibility) values (v_version, v_gs, pg_temp.pkid('topic:NS'), $t$Writing and solving number sentences$t$, $t$Learners turn a story into a number sentence and solve it by inspection.$t$, 40, 'standard', 'en', $t$A number sentence uses numbers, an operation and an equals sign, with a box for the unknown. The unknown can be anywhere in the sentence. Examples are Funda360 examples, not DBE examples. This is a draft that a curriculum specialist has not yet checked.$t$, $t$Read the story, write the number sentence, then think what number fits the box.$t$, 1, $j${"reading_level":"Grade 4","offline_ready":true,"low_resource":true}$j$::jsonb) returning id into v_id;
