  insert into public.learning_activities (lesson_id, curriculum_version_id, title, instructions, activity_type, grouping, difficulty, estimated_minutes, resource_id, sort_order) values (pg_temp.pkid('lesson:L06'), v_version, $t$Practice set$t$, $t$Write a number sentence for each story and solve it.$t$, $t$individual_practice$t$, $t$individual$t$, $t$standard$t$, 15, pg_temp.pkid($t$res:L06:Practice set: write and solve$t$), 2);
  insert into public.lessons (curriculum_version_id, grade_subject_id, topic_id, title, description, estimated_minutes, difficulty, language, teacher_notes, learner_instructions, sort_order, accessibility) values (v_version, v_gs, pg_temp.pkid('topic:NS'), $t$Trial and improvement, and checking by substitution$t$, $t$Learners solve number sentences by making a sensible guess and improving it, then check the answer by substituting it back.$t$, 40, 'standard', 'en', $t$Make the improving step visible: too small means try bigger, too big means try smaller. Substitution means putting the answer back in the number sentence to see if it is true. Examples are Funda360 examples, not DBE examples. This is a draft that a curriculum specialist has not yet checked.$t$, $t$Guess, test, improve. Then put your answer back into the sentence to check it.$t$, 2, $j${"reading_level":"Grade 4","offline_ready":true,"low_resource":true}$j$::jsonb) returning id into v_id;
