  insert into public.content_source_references (entity_table, entity_id, source_id, locator, supports) values ('lessons', v_id, pg_temp.pkid('src:caps'), $t$CAPS Mathematics Grades 4-6, Grade 4 Term 1 (section 3.3.1, from printed page 35 per docs/sources; item-level page NOT verified)$t$, $t$Requirements background for NS.03, NS.04$t$);
