  insert into public.learning_activities (lesson_id, curriculum_version_id, title, instructions, activity_type, grouping, difficulty, estimated_minutes, resource_id, sort_order) values (pg_temp.pkid('lesson:L07'), v_version, $t$Practice set$t$, $t$Solve and check each number sentence.$t$, $t$individual_practice$t$, $t$individual$t$, $t$standard$t$, 15, pg_temp.pkid($t$res:L07:Practice set: trial and improvement$t$), 2);
  insert into public.lessons (curriculum_version_id, grade_subject_id, topic_id, title, description, estimated_minutes, difficulty, language, teacher_notes, learner_instructions, sort_order, accessibility) values (v_version, v_gs, pg_temp.pkid('topic:NS'), $t$Properties of operations: order, grouping, parts and zero$t$, $t$Learners notice when the order or grouping of numbers does or does not change an answer, break a number into parts to multiply, and see what adding 0 does.$t$, 45, 'standard', 'en', $t$Let learners notice each pattern with counters first and name it afterwards. Always ask: does the order matter here? Show that subtraction behaves differently so the properties are not over-applied. Do not ask learners to memorise the names without understanding. Examples are Funda360 examples, not DBE examples. This is a draft that a curriculum specialist has not yet checked.$t$, $t$Try it with counters first. Then say what stays the same and what changes.$t$, 3, $j${"reading_level":"Grade 4","offline_ready":true,"low_resource":true}$j$::jsonb) returning id into v_id;
  insert into pk values ('lesson:L08', v_id);
