  insert into public.content_source_references (entity_table, entity_id, source_id, locator, supports) values ('lessons', v_id, pg_temp.pkid('src:atp'), $t$2026 Grade 4 Mathematics ATP, Term 1, Number sentences: commutative, associative and distributive properties; additive property of 0 (item-level page and week NOT verified)$t$, $t$Mapped to NS.05, NS.06, NS.07, NS.08$t$);
  insert into public.content_source_references (entity_table, entity_id, source_id, locator, supports) values ('lessons', v_id, pg_temp.pkid('src:caps'), $t$CAPS Mathematics Grades 4-6, Grade 4 Term 1 (section 3.3.1, from printed page 35 per docs/sources; item-level page NOT verified)$t$, $t$Requirements background for NS.05, NS.06, NS.07, NS.08$t$);
