  insert into public.learning_activities (lesson_id, curriculum_version_id, title, instructions, activity_type, grouping, difficulty, estimated_minutes, resource_id, sort_order) values (pg_temp.pkid('lesson:L08'), v_version, $t$Practice set$t$, $t$Complete the practice set on your own.$t$, $t$individual_practice$t$, $t$individual$t$, $t$standard$t$, 15, pg_temp.pkid($t$res:L08:Practice set: properties$t$), 2);
  insert into public.lessons (curriculum_version_id, grade_subject_id, topic_id, title, description, estimated_minutes, difficulty, language, teacher_notes, learner_instructions, sort_order, accessibility) values (v_version, v_gs, pg_temp.pkid('topic:AS'), $t$Adding and subtracting by building up and breaking down$t$, $t$Learners add and subtract four-digit numbers by breaking one number into parts or building up in friendly jumps.$t$, 45, 'standard', 'en', $t$Show both directions: breaking down (add or subtract the parts) and building up (jump to a friendly number, then on). Ask what each step does so the method is understood, not copied. Examples are Funda360 examples, not DBE examples. This is a draft that a curriculum specialist has not yet checked.$t$, $t$Break the number into parts, or build up in jumps. Say what each step does.$t$, 1, $j${"reading_level":"Grade 4","offline_ready":true,"low_resource":true}$j$::jsonb) returning id into v_id;
