  insert into public.lessons (curriculum_version_id, grade_subject_id, topic_id, title, description, estimated_minutes, difficulty, language, teacher_notes, learner_instructions, sort_order, accessibility) values (v_version, v_gs, pg_temp.pkid('topic:AS'), $t$Number lines and estimation$t$, $t$Learners add and subtract with jumps on an empty number line and use estimation to check that an answer makes sense.$t$, 40, 'standard', 'en', $t$Estimation is for checking, so ask learners to estimate before they calculate and compare afterwards. An estimate is close, not exact. Examples are Funda360 examples, not DBE examples. This is a draft that a curriculum specialist has not yet checked.$t$, $t$Estimate first, then use a number line, then compare your answer with your estimate.$t$, 2, $j${"reading_level":"Grade 4","offline_ready":true,"low_resource":true}$j$::jsonb) returning id into v_id;
