  insert into public.lessons (curriculum_version_id, grade_subject_id, topic_id, title, description, estimated_minutes, difficulty, language, teacher_notes, learner_instructions, sort_order, accessibility) values (v_version, v_gs, pg_temp.pkid('topic:AS'), $t$Rounding and compensating, and checking with inverse operations$t$, $t$Learners change a number to a friendly one, adjust the answer, and check an answer with the inverse operation.$t$, 40, 'standard', 'en', $t$Compensating only makes sense when learners can say why the adjustment is needed. Use a number line to show it. Inverse means the operation that undoes the first. Examples are Funda360 examples, not DBE examples. This is a draft that a curriculum specialist has not yet checked.$t$, $t$Make the number friendly, then say how you fix the answer. Check with the inverse.$t$, 3, $j${"reading_level":"Grade 4","offline_ready":true,"low_resource":true}$j$::jsonb) returning id into v_id;
