  insert into public.lessons (curriculum_version_id, grade_subject_id, topic_id, title, description, estimated_minutes, difficulty, language, teacher_notes, learner_instructions, sort_order, accessibility) values (v_version, v_gs, pg_temp.pkid('topic:MUL'), $t$Multiplying one-digit numbers by numbers up to 10$t$, $t$Learners build the multiplication facts they need by using arrays, doubling, halving and building up.$t$, 40, 'standard', 'en', $t$Facts are built from strategies, not only recited. Use arrays so learners see why 6 × 8 and 8 × 6 match. Examples are Funda360 examples, not DBE examples. This is a draft that a curriculum specialist has not yet checked.$t$, $t$Use an array or a strategy to work out each fact, and say how you did it.$t$, 1, $j${"reading_level":"Grade 4","offline_ready":true,"low_resource":true}$j$::jsonb) returning id into v_id;
