  insert into public.lessons (curriculum_version_id, grade_subject_id, topic_id, title, description, estimated_minutes, difficulty, language, teacher_notes, learner_instructions, sort_order, accessibility) values (v_version, v_gs, pg_temp.pkid('topic:MUL'), $t$Multiplying a two-digit number by a one-digit number$t$, $t$Learners multiply two-digit (and larger) numbers by one-digit numbers by breaking numbers down, doubling and estimating.$t$, 45, 'standard', 'en', $t$Link breaking down to the distributive property from the properties lesson. Estimate first so learners can tell if the answer is sensible. The ATP lists inverse operations among the multiplication strategies. Use them only as a check with facts learners know; the project's ATP record does not say whether division is expected in Term 1, so a curriculum specialist should confirm. Examples are Funda360 examples, not DBE examples. This is a draft that a curriculum specialist has not yet checked.$t$, $t$Estimate, then break the number down or use doubling. Check that your answer is sensible.$t$, 2, $j${"reading_level":"Grade 4","offline_ready":true,"low_resource":true}$j$::jsonb) returning id into v_id;
