  insert into public.lessons (curriculum_version_id, grade_subject_id, topic_id, title, description, estimated_minutes, difficulty, language, teacher_notes, learner_instructions, sort_order, accessibility) values (v_version, v_gs, pg_temp.pkid('topic:MUL'), $t$Multiplying by a two-digit number$t$, $t$Learners multiply a number of at least two digits by a two-digit number by breaking down, using a grid, and doubling and halving.$t$, 45, 'standard', 'en', $t$A grid (area) model shows why the parts add up. Always estimate first. Keep the numbers in the ATP scope: do not move to multiplication of much larger numbers. Examples are Funda360 examples, not DBE examples. This is a draft that a curriculum specialist has not yet checked.$t$, $t$Estimate first. Then break the second number into tens and ones, or use doubling and halving.$t$, 3, $j${"reading_level":"Grade 4","offline_ready":true,"low_resource":true}$j$::jsonb) returning id into v_id;
