  insert into public.lessons (curriculum_version_id, grade_subject_id, topic_id, title, description, estimated_minutes, difficulty, language, teacher_notes, learner_instructions, sort_order, accessibility) values (v_version, v_gs, pg_temp.pkid('topic:PS'), $t$Money problems with whole numbers$t$, $t$Learners solve whole-number problems about money, using a number sentence and an estimate.$t$, 45, 'standard', 'en', $t$Use whole rands so every answer is a whole number. Teach a routine: read, find the question, choose the operation, write the number sentence, estimate, solve, check, answer with the unit. Contexts are Funda360 examples, not DBE examples. Examples are Funda360 examples, not DBE examples. This is a draft that a curriculum specialist has not yet checked.$t$, $t$Follow the steps: read, number sentence, estimate, solve, check, answer in rands.$t$, 1, $j${"reading_level":"Grade 4","offline_ready":true,"low_resource":true}$j$::jsonb) returning id into v_id;
