  insert into public.lessons (curriculum_version_id, grade_subject_id, topic_id, title, description, estimated_minutes, difficulty, language, teacher_notes, learner_instructions, sort_order, accessibility) values (v_version, v_gs, pg_temp.pkid('topic:FA'), $t$Getting ready for the Term 1 assignment$t$, $t$Learners revise the areas the Term 1 assignment covers, and teachers see what the ATP records about the assignment.$t$, 45, 'standard', 'en', $t$The 2026 ATP records a Term 1 assignment covering whole numbers (counting, ordering and representing), number sentences, and whole-number addition and subtraction, completed in class within three hours. Funda360 does not hold the assignment, its marks, its weighting or its marking guideline. Use the official ATP and your school's assessment policy for those. The revision material here is Funda360 practice, not the DBE assignment. Examples are Funda360 examples, not DBE examples. This is a draft that a curriculum specialist has not yet checked.$t$, $t$Use the checklist to see what you can already do. Practise the parts you are not sure about.$t$, 1, $j${"reading_level":"Grade 4","offline_ready":true,"low_resource":true}$j$::jsonb) returning id into v_id;
