-- Funda360 content pack: Grade 4 Mathematics, Term 1, reconciled with the 2026 ATP (DRAFT, NOT VERIFIED).
--
-- This is DATA, not a migration, so it never reaches production through `supabase db push`. It is loaded by the
-- RLS test harness (just in time for its own suite) and a platform administrator may run it against a database on
-- purpose. Idempotent: if the version below already exists it does nothing.
--
-- WHAT THIS IS
--   A new draft curriculum version, additive to the earlier draft pack (ZA-CAPS-G4-MATH-SLICE), which is kept
--   as history and annotated as superseded (only while it is still a draft). Scope is taken ONLY from the Term 1
--   bullets recorded in docs/sources/caps/grade4-mathematics-2026-atp.md. The 2026 ATP decides what belongs in
--   Term 1 and in what order; CAPS gives the requirements behind it. Nothing from either document is copied:
--   objectives are Funda360 paraphrases, and examples are Funda360's own.
--
-- WHAT THIS IS NOT
--   Not verified, not approved, not published, not "CAPS aligned". The PDFs could not be downloaded from the build
--   environment, so no checksum was recorded and no page or week reference below is verified. Every unit is linked
--   to its source through content_source_references with NO check result, and content_verifications is left
--   empty. A curriculum specialist must check every objective, then a person other than the author must approve.
--   Do not run the AI generator against this version until that review is done.
--
-- Generated pack: 17 lessons, 112 resources, 34 activities, 6 practice assessments (60 questions).

create temp table if not exists pk (k text primary key, id uuid not null);

create or replace function pg_temp.pkid(p_k text) returns uuid language sql as $f$
  select id from pk where k = p_k
$f$;

create or replace function pg_temp.add_resource(
  p_lesson text, p_sort integer, p_stage text, p_kind text, p_title text, p_summary text, p_body jsonb, p_diff text, p_mins integer,
  p_fmt text[], p_printable boolean, p_size integer, p_objs text[], p_locator text)
returns void language plpgsql as $f$
declare
  v_id uuid;
  v_o  text;
begin
     delivery_formats, connectivity, device, projector_required, printable, cacheable, size_kb)
  select pg_temp.pkid('version'), pg_temp.pkid('gs'), l.topic_id, p_stage::public.toolkit_stage, p_kind, p_title, p_summary, p_body, p_diff::public.content_difficulty, 'en', p_mins,
         p_fmt, 'none', 'none', false, p_printable, true, p_size
  from public.lessons l where l.id = pg_temp.pkid('lesson:' || p_lesson)
  returning id into v_id;
  values (pg_temp.pkid('lesson:' || p_lesson), v_id, pg_temp.pkid('version'), p_sort);
  foreach v_o in array p_objs loop
  end loop;
  values ('teaching_resources', v_id, pg_temp.pkid('src:atp'), p_locator, 'Mapped to ' || array_to_string(p_objs, ', '));
end $f$;

create or replace function pg_temp.add_question(
  p_assess text, p_pos integer, p_type text, p_prompt text, p_options jsonb, p_marks integer, p_obj text, p_diff text,
  p_answer jsonb, p_feedback text, p_notes text)
returns void language plpgsql as $f$
declare v_q uuid;
begin
  values (pg_temp.pkid('assess:' || p_assess), pg_temp.pkid('version'), p_pos, p_type, p_prompt, coalesce(p_options, '[]'::jsonb), p_marks,
          pg_temp.pkid('obj:' || p_obj), p_diff::public.content_difficulty)
  returning id into v_q;
  values (v_q, pg_temp.pkid('assess:' || p_assess), p_answer, p_feedback, p_notes);
end $f$;

do $pack$
declare
  v_version uuid;
  v_old     uuid;
  v_phase   uuid;
  v_grade   uuid;
  v_subject uuid;
  v_gs      uuid;
  v_term    uuid;
  v_id      uuid;
  v_src     uuid;
begin
  if exists (select 1 from public.curriculum_versions where code = 'ZA-G4-MATH-2026-T1') then
    raise notice 'content pack ZA-G4-MATH-2026-T1 already loaded; nothing to do';
    return;
  end if;
  select id into v_old from public.curriculum_versions where code = 'ZA-CAPS-G4-MATH-SLICE';

  -- 1. Sources: registered, never verified, no checksum (the documents could not be downloaded here) ----
  select id into v_src from public.curriculum_sources where title = 'Curriculum and Assessment Policy Statement (CAPS): Mathematics, Intermediate Phase, Grades 4-6';
  if v_src is null then
    values ('Curriculum and Assessment Policy Statement (CAPS): Mathematics, Intermediate Phase, Grades 4-6', 'Department of Basic Education, South Africa', 'caps_policy',
            $t$https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20IP%20%20MATHEMATICS%20GR%204-6%20web.pdf$t$, '2011, ISBN 978-1-4315-0491-6 (as recorded in docs/sources; not independently checked)',
            'Not yet confirmed. Funda360 keeps a reference and its own paraphrase only; the permission position is a decision for the project owner.', false,
            'registered',
            'NOT VERIFIED. Whether this URL and the other DBE URLs in docs/sources are the same document is unconfirmed, and no checksum is recorded because the PDF could not be downloaded from the build environment. Run docs/sources/verify-dbe-sources.sh from an unrestricted machine.')
    returning id into v_src;
  end if;
  select id into v_src from public.curriculum_sources where title = '2026 Annual Teaching Plan: Mathematics Grade 4 (English)';
  if v_src is null then
    values ('2026 Annual Teaching Plan: Mathematics Grade 4 (English)', 'Department of Basic Education, South Africa', 'annual_teaching_plan',
            $t$https://www.education.gov.za/Portals/0/Documents/Recovery%20plan%20page/2026%20ATPs/2026_ATP_Mathematics_Grade%204.pdf?ver=2026-01-20-202040-057$t$, '2026',
            'Not yet confirmed. Funda360 keeps a reference and its own paraphrase only; the permission position is a decision for the project owner.', false,
            'registered',
            'NOT VERIFIED. Scope was taken from the Term 1 bullets recorded in docs/sources/caps/grade4-mathematics-2026-atp.md. The PDF could not be downloaded from the build environment, so there is no checksum and no page or week reference has been verified.')
    returning id into v_src;
  end if;

  -- 2. Version and hierarchy (draft) --------------------------------------------------------
  values ('ZA-G4-MATH-2026-T1', 'Grade 4 Mathematics, Term 1 (2026 ATP reconciliation, DRAFT NOT VERIFIED)', '2026-t1-draft-1',
          'Department of Basic Education, South Africa',
          'Scope and sequence: DBE 2026 Grade 4 Mathematics ATP, Term 1. Requirements: DBE CAPS Mathematics Grades 4-6 (Grade 4 Term 1 from printed page 35 per docs/sources). Both are recorded in docs/sources and are NOT verified. Item-level page and week references are not verified.',
          'Funda360 paraphrase and examples. No DBE text is copied. Permission to reference the documents is unconfirmed. DRAFT: not reviewed by a curriculum specialist, not approved, not published.',
          v_old)
  returning id into v_version;

  -- weeks are left empty: the project's ATP record does not give the number of weeks


  -- 3. Topics, subtopics, objectives, skills -------------------------------------------------

  -- 4. Lessons, toolkit resources and activities -------------------------------------------
  perform pg_temp.add_resource($t$L01$t$, 1, $t$explain$t$, $t$teacher_explanation$t$, $t$Counting in equal steps$t$, $t$What counting in steps means and the patterns to point out.$t$, $j${"blocks":[{"type":"tip","text":"Funda360 example. It is not taken from the DBE documents."},{"type":"heading","text":"Say it in words"},{"type":"paragraph","text":"Counting in steps means we add (or take away) the same number each time. In Term 1 learners count forwards and backwards in 2s, 3s, 5s, 10s, 25s, 50s and 100s, with numbers between 0 and at least 10 000."},{"type":"steps","items":["Write the start number and the step on the board, for example: start at 0, count in 25s.","Count aloud together and write each number as you say it.","Ask: what changes each time? What stays the same?","Count backwards from a bigger number, for example from 1 000 in 50s.","Point out the patterns: two 50s make 100, four 25s make 100, ten 10s make 100 and ten 100s make 1 000."]}]}$j$::jsonb, $t$standard$t$, 10, array[$t$text$t$,$t$teacher_led$t$]::text[], false, 1, array[$t$WN.01$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole numbers: counting forwards and backwards (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L01$t$, 2, $t$show$t$, $t$diagram$t$, $t$Number line: counting in 25s$t$, $t$A number line drawn on the board, jumping in 25s.$t$, $j${"blocks":[{"type":"paragraph","text":"Draw a number line and jump in 25s from 0. Write each landing number under the line."},{"type":"table","headers":["Start","+25","+25","+25","+25","+25","+25"],"rows":[["0","25","50","75","100","125","150"]]}],"alt_text":"A number line that starts at 0 and jumps in equal steps of 25, landing on 25, 50, 75, 100, 125 and 150."}$j$::jsonb, $t$standard$t$, 5, array[$t$visual$t$,$t$teacher_led$t$]::text[], false, 1, array[$t$WN.01$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole numbers: counting forwards and backwards (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L01$t$, 3, $t$try$t$, $t$classroom_activity$t$, $t$Count with bottle tops$t$, $t$Groups make piles of bottle tops and count them in steps.$t$, $j${"blocks":[{"type":"paragraph","text":"Materials: about 100 bottle tops, stones or paper squares for each group."},{"type":"steps","items":["Make piles of 5. Count the piles aloud: 5, 10, 15 and on to 100.","Make piles of 10 and count again. Then make piles of 2.","Count backwards from 100 as the group takes piles away.","Write the numbers you said on paper."]}]}$j$::jsonb, $t$standard$t$, 15, array[$t$practical$t$,$t$teacher_led$t$]::text[], false, 1, array[$t$WN.01$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole numbers: counting forwards and backwards (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L01$t$, 4, $t$practise$t$, $t$exercise$t$, $t$Practice set: counting in steps$t$, $t$Eight patterns to complete.$t$, $j${"blocks":[{"type":"numbered","items":["Count in 2s: 14, 16, 18, __, __","Count in 5s: 35, 40, __, __, __","Count backwards in 10s: 1 000, 990, __, __, __","Count in 25s: 0, 25, 50, __, __, __","Count in 50s: 350, 400, __, __, __","Count in 100s: 4 300, 4 400, __, __, __","Count backwards in 3s: 30, 27, __, __, __","Count backwards in 100s: 9 800, 9 700, __, __, __"]},{"type":"tip","text":"Answers for the teacher: 1) 20, 22; 2) 45, 50, 55; 3) 980, 970, 960; 4) 75, 100, 125; 5) 450, 500, 550; 6) 4 500, 4 600, 4 700; 7) 24, 21, 18; 8) 9 600, 9 500, 9 400"}]}$j$::jsonb, $t$standard$t$, 15, array[$t$text$t$,$t$teacher_led$t$]::text[], false, 1, array[$t$WN.01$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole numbers: counting forwards and backwards (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L01$t$, 5, $t$support$t$, $t$remediation$t$, $t$Support: counting on a hundred chart$t$, $t$Colour the numbers you say on a chart from 1 to 100.$t$, $j${"blocks":[{"type":"steps","items":["Give each learner a hundred chart (1 to 100) drawn on paper, or draw one on the board.","Colour every number you say when counting in 2s. Look at the pattern.","Do the same for 5s and 10s on new charts.","Say the numbers aloud while pointing, then cover the chart and try again.","When secure, count in 10s past 100: 100, 110, 120 and on."]}]}$j$::jsonb, $t$foundational$t$, 15, array[$t$practical$t$,$t$teacher_led$t$]::text[], false, 1, array[$t$WN.01$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole numbers: counting forwards and backwards (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L01$t$, 6, $t$challenge$t$, $t$extension$t$, $t$Challenge: find the step$t$, $t$Reasoning about steps, not bigger sums.$t$, $j${"blocks":[{"type":"numbered","items":["A pattern starts 1 250, 1 350, 1 450. What is the step? What are the next three numbers?","Thandi counts in 50s from 0. Will she say 975? Explain how you know.","Two learners count from 0, one in 25s and one in 50s. Which numbers up to 200 do they both say?"]},{"type":"tip","text":"Answers for the teacher: 1) the step is 100; 1 550, 1 650, 1 750; 2) No. Counting in 50s the numbers end in 00 or 50, so she says 950 and then 1 000.; 3) 50, 100, 150, 200"}]}$j$::jsonb, $t$advanced$t$, 15, array[$t$text$t$]::text[], false, 1, array[$t$WN.01$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole numbers: counting forwards and backwards (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L01$t$, 7, $t$check$t$, $t$formative_questions$t$, $t$Questions to ask: Counting in steps up to 10 000$t$, $t$Oral questions that show quickly who understands.$t$, $j${"blocks":[{"type":"numbered","items":["What are the next two numbers: 75, 100, 125, __, __?","Count backwards in 10s from 500. What are the first three numbers you say?","How many 25s make 100?"]},{"type":"tip","text":"Answers for the teacher: 1) 150, 175; 2) 490, 480, 470; 3) 4"},{"type":"tip","text":"Ask learners to answer on their fingers, a slate or a scrap of paper so you can see everyone."}]}$j$::jsonb, $t$standard$t$, 5, array[$t$teacher_led$t$]::text[], false, 1, array[$t$WN.01$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole numbers: counting forwards and backwards (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L02$t$, 1, $t$explain$t$, $t$teacher_explanation$t$, $t$What each digit is worth$t$, $t$A short script on thousands, hundreds, tens and ones.$t$, $j${"blocks":[{"type":"tip","text":"Funda360 example. It is not taken from the DBE documents."},{"type":"paragraph","text":"In 4 382 the digit 4 is in the thousands place, so it is worth 4 000. The 3 is worth 300, the 8 is worth 80 and the 2 is worth 2."},{"type":"steps","items":["Write 4 382 on the board and name each place under its digit.","Say the value of each digit: 4 000, 300, 80, 2.","Write the expanded form: 4 000 + 300 + 80 + 2.","Ask learners to say the number in words: four thousand three hundred and eighty-two."]}]}$j$::jsonb, $t$standard$t$, 10, array[$t$text$t$,$t$teacher_led$t$]::text[], false, 1, array[$t$WN.03$t$,$t$WN.05$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole numbers: representing numbers and place value (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L02$t$, 2, $t$explain$t$, $t$worked_example$t$, $t$Showing 4 382 in different ways$t$, $t$The same number shown six ways.$t$, $j${"blocks":[{"type":"steps","items":["Digits: 4 382","Words: four thousand three hundred and eighty-two","Expanded form: 4 000 + 300 + 80 + 2","Place value chart: Th 4, H 3, T 8, O 2","Bundles or counters: 4 thousands, 3 hundreds, 8 tens and 2 ones drawn as squares, strips and dots","Number line: between 4 000 and 5 000, a little past 4 300"]},{"type":"tip","text":"A zero is a place holder. In 4 038 the zero shows there are no hundreds, which is why 4 038 and 4 308 are different numbers."}]}$j$::jsonb, $t$standard$t$, 8, array[$t$text$t$]::text[], false, 1, array[$t$WN.03$t$,$t$WN.05$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole numbers: representing numbers and place value (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L02$t$, 3, $t$show$t$, $t$diagram$t$, $t$Place value chart (draw on the board)$t$, $t$How to draw the chart so every learner can see it.$t$, $j${"blocks":[{"type":"paragraph","text":"Draw four columns on the board and label them Th, H, T, O."},{"type":"table","headers":["Th","H","T","O"],"rows":[["4","3","8","2"]]},{"type":"tip","text":"Use a different chalk colour for each column."}],"alt_text":"A place value chart with four columns labelled thousands, hundreds, tens and ones. The digits 4, 3, 8 and 2 are written under them."}$j$::jsonb, $t$standard$t$, 5, array[$t$visual$t$,$t$teacher_led$t$]::text[], false, 1, array[$t$WN.03$t$,$t$WN.05$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole numbers: representing numbers and place value (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L02$t$, 4, $t$try$t$, $t$classroom_activity$t$, $t$Build numbers with bundles or counters$t$, $t$Groups build a number with counters or drawn shapes.$t$, $j${"blocks":[{"type":"paragraph","text":"Materials: bundles of 10 sticks, bottle tops, or squares, strips and dots drawn on paper."},{"type":"steps","items":["Give each group a number card, for example 2 305.","The group shows the number with the materials.","They write the number in words and in expanded form.","Groups swap cards and check each other."]}]}$j$::jsonb, $t$standard$t$, 15, array[$t$practical$t$,$t$teacher_led$t$]::text[], false, 1, array[$t$WN.03$t$,$t$WN.05$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole numbers: representing numbers and place value (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L02$t$, 5, $t$practise$t$, $t$exercise$t$, $t$Practice set: represent four-digit numbers$t$, $t$Six questions on expanded form, value and words.$t$, $j${"blocks":[{"type":"numbered","items":["Write 5 206 in expanded form.","What is the value of the 3 in 6 349?","Write 7 000 + 40 + 8 as one number.","Write 3 710 in words.","Which digit is in the tens place in 8 524?","Write the number: nine thousand and sixty-one."]},{"type":"tip","text":"Answers for the teacher: 1) 5 000 + 200 + 6; 2) 300; 3) 7 048; 4) three thousand seven hundred and ten; 5) 2; 6) 9 061"}]}$j$::jsonb, $t$standard$t$, 15, array[$t$text$t$]::text[], false, 1, array[$t$WN.03$t$,$t$WN.05$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole numbers: representing numbers and place value (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L02$t$, 6, $t$support$t$, $t$remediation$t$, $t$Support: three-digit numbers with counters$t$, $t$Build numbers to 999 on a paper chart first.$t$, $j${"blocks":[{"type":"steps","items":["Give each learner counters and a paper chart with hundreds, tens and ones.","Build 214 with 2 counters in hundreds, 1 in tens and 4 in ones.","Say the number and its expanded form together.","Change one counter and say the new number. Repeat.","When secure, add a thousands column."]}]}$j$::jsonb, $t$foundational$t$, 15, array[$t$practical$t$,$t$teacher_led$t$]::text[], false, 1, array[$t$WN.03$t$,$t$WN.05$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole numbers: representing numbers and place value (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L02$t$, 7, $t$challenge$t$, $t$extension$t$, $t$Challenge: what could the number be?$t$, $t$Reasoning about digits and place value.$t$, $j${"blocks":[{"type":"numbered","items":["I have four digits. My thousands digit is 6, my tens digit is 0 and my digits add up to 14. Write two numbers I could be.","Why are 4 038 and 4 308 different numbers when they use the same digits?"]},{"type":"tip","text":"Answers for the teacher: 1) for example 6 305 and 6 800; 2) The 3 is worth 30 in 4 038 but 300 in 4 308."}]}$j$::jsonb, $t$advanced$t$, 15, array[$t$text$t$]::text[], false, 1, array[$t$WN.03$t$,$t$WN.05$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole numbers: representing numbers and place value (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L02$t$, 8, $t$check$t$, $t$formative_questions$t$, $t$Questions to ask: Place value and representing four-digit numbers$t$, $t$Oral questions that show quickly who understands.$t$, $j${"blocks":[{"type":"numbered","items":["What is the value of the 7 in 7 420?","What is 4 000 + 20 + 5?","Show 3 060 in expanded form."]},{"type":"tip","text":"Answers for the teacher: 1) 7 000; 2) 4 025; 3) 3 000 + 60"},{"type":"tip","text":"Ask learners to answer on their fingers, a slate or a scrap of paper so you can see everyone."}]}$j$::jsonb, $t$standard$t$, 5, array[$t$teacher_led$t$]::text[], false, 1, array[$t$WN.03$t$,$t$WN.05$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole numbers: representing numbers and place value (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L03$t$, 1, $t$explain$t$, $t$teacher_explanation$t$, $t$Comparing from the left$t$, $t$How to decide which number is bigger.$t$, $j${"blocks":[{"type":"tip","text":"Funda360 example. It is not taken from the DBE documents."},{"type":"steps","items":["Count the digits. A number with more digits is bigger.","If the digits are the same, compare thousands first, then hundreds, then tens, then ones.","Compare 4 380 and 4 308: thousands are the same (4), hundreds are the same (3), tens are 8 and 0. So 4 380 > 4 308.","Write the symbol with the open side facing the bigger number.","To order, find the smallest first (ascending) or the biggest first (descending): 2 009 < 2 090 < 2 900."]}]}$j$::jsonb, $t$standard$t$, 10, array[$t$text$t$,$t$teacher_led$t$]::text[], false, 1, array[$t$WN.02$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole numbers: ordering and comparing (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L03$t$, 2, $t$try$t$, $t$classroom_activity$t$, $t$Human number line$t$, $t$Learners hold number cards and put themselves in order.$t$, $j${"blocks":[{"type":"steps","items":["Give each of six learners a four-digit number card.","They arrange themselves from smallest to largest.","The class checks: ask which place decided each pair.","Swap two learners. Who is out of place?"]}]}$j$::jsonb, $t$standard$t$, 15, array[$t$practical$t$,$t$teacher_led$t$]::text[], false, 1, array[$t$WN.02$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole numbers: ordering and comparing (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L03$t$, 3, $t$practise$t$, $t$exercise$t$, $t$Practice set: order and compare$t$, $t$Six questions on ordering and symbols.$t$, $j${"blocks":[{"type":"numbered","items":["Put in order from smallest to largest: 5 120, 5 012, 5 210","Put in order from largest to smallest: 7 305, 7 350, 7 035","Write <, > or =: 6 408 __ 6 480","Write <, > or =: 3 999 __ 4 000","Write <, > or =: 8 500 __ 8 500","Which is greater: 9 087 or 9 078?"]},{"type":"tip","text":"Answers for the teacher: 1) 5 012, 5 120, 5 210; 2) 7 350, 7 305, 7 035; 3) <; 4) <; 5) =; 6) 9 087"}]}$j$::jsonb, $t$standard$t$, 15, array[$t$text$t$]::text[], false, 1, array[$t$WN.02$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole numbers: ordering and comparing (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L03$t$, 4, $t$support$t$, $t$remediation$t$, $t$Support: comparing numbers to 1 000$t$, $t$Compare three-digit numbers with place value cards.$t$, $j${"blocks":[{"type":"steps","items":["Give pairs of learners place value cards for hundreds, tens and ones.","Build 342 and 324 side by side.","Compare the hundreds, then the tens. Say which is bigger and why.","Write the symbol. Repeat with new pairs."]}]}$j$::jsonb, $t$foundational$t$, 15, array[$t$practical$t$,$t$teacher_led$t$]::text[], false, 1, array[$t$WN.02$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole numbers: ordering and comparing (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L03$t$, 5, $t$challenge$t$, $t$extension$t$, $t$Challenge: reason about order$t$, $t$Spotting mistakes and finding numbers that fit.$t$, $j${"blocks":[{"type":"numbered","items":["Write a number between 6 450 and 6 460.","Use the digits 3, 0, 8 and 5 once each. Write the smallest and the largest four-digit number you can. (A four-digit number cannot start with 0.)","Amina says 1 099 is greater than 1 100 because 99 is bigger than 10. What is her mistake?"]},{"type":"tip","text":"Answers for the teacher: 1) for example 6 455; 2) 3 058 and 8 530; 3) She compared the last two digits. The hundreds decide: 0 hundreds is less than 1 hundred."}]}$j$::jsonb, $t$advanced$t$, 15, array[$t$text$t$]::text[], false, 1, array[$t$WN.02$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole numbers: ordering and comparing (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L03$t$, 6, $t$check$t$, $t$formative_questions$t$, $t$Questions to ask: Ordering and comparing whole numbers$t$, $t$Oral questions that show quickly who understands.$t$, $j${"blocks":[{"type":"numbered","items":["Which is more, 4 305 or 4 350?","Which symbol makes this true: 2 999 __ 3 001?","What number comes just before 5 000?"]},{"type":"tip","text":"Answers for the teacher: 1) 4 350; 2) <; 3) 4 999"},{"type":"tip","text":"Ask learners to answer on their fingers, a slate or a scrap of paper so you can see everyone."}]}$j$::jsonb, $t$standard$t$, 5, array[$t$teacher_led$t$]::text[], false, 1, array[$t$WN.02$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole numbers: ordering and comparing (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L04$t$, 1, $t$explain$t$, $t$teacher_explanation$t$, $t$Odd or even?$t$, $t$Pairs, and why the ones digit decides.$t$, $j${"blocks":[{"type":"tip","text":"Funda360 example. It is not taken from the DBE documents."},{"type":"paragraph","text":"An even number can be made into pairs with none left over. An odd number always has one left over."},{"type":"steps","items":["Show 7 counters and make pairs. One is left, so 7 is odd.","Show 8 counters. No counter is left, so 8 is even.","Even numbers end in 0, 2, 4, 6 or 8. Odd numbers end in 1, 3, 5, 7 or 9.","Why only the ones digit? Tens, hundreds and thousands are made of whole tens, so they can always be paired. Test 387: 38 tens can be paired, and the 7 ones leave one over."]}]}$j$::jsonb, $t$standard$t$, 10, array[$t$text$t$,$t$teacher_led$t$]::text[], false, 1, array[$t$WN.04$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole numbers: odd and even numbers (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L04$t$, 2, $t$try$t$, $t$group_activity$t$, $t$Stand up, sit down$t$, $t$A whole-class game with no materials.$t$, $j${"blocks":[{"type":"steps","items":["Call out a number. Even numbers: stand up. Odd numbers: sit down.","Use numbers up to 1 000, for example 468, 995 and 1 000.","Ask one learner to explain how they decided."]}]}$j$::jsonb, $t$standard$t$, 10, array[$t$practical$t$,$t$teacher_led$t$]::text[], false, 1, array[$t$WN.04$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole numbers: odd and even numbers (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L04$t$, 3, $t$practise$t$, $t$exercise$t$, $t$Practice set: odd or even$t$, $t$Eight questions.$t$, $j${"blocks":[{"type":"numbered","items":["Write odd or even: 38","Write odd or even: 75","Write odd or even: 460","Write odd or even: 987","Write odd or even: 1 000","Write odd or even: 603","What is the next even number after 698?","What is the next odd number after 999?"]},{"type":"tip","text":"Answers for the teacher: 1) even; 2) odd; 3) even; 4) odd; 5) even; 6) odd; 7) 700; 8) 1 001"}]}$j$::jsonb, $t$standard$t$, 10, array[$t$text$t$]::text[], false, 1, array[$t$WN.04$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole numbers: odd and even numbers (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L04$t$, 4, $t$support$t$, $t$remediation$t$, $t$Support: sort number cards into pairs$t$, $t$Sort cards 1 to 20 into odd and even piles.$t$, $j${"blocks":[{"type":"steps","items":["Write the numbers 1 to 20 on cards.","Take a card and make that many counters in pairs.","Put it on the odd pile or the even pile.","Look at the last digits in each pile. What do you notice?"]}]}$j$::jsonb, $t$foundational$t$, 15, array[$t$practical$t$,$t$teacher_led$t$]::text[], false, 1, array[$t$WN.04$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole numbers: odd and even numbers (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L04$t$, 5, $t$challenge$t$, $t$extension$t$, $t$Challenge: test a pattern$t$, $t$Thinking about odd and even, not just labelling.$t$, $j${"blocks":[{"type":"numbered","items":["Is 1 000 odd or even? How do you know?","Use the digits 4, 7 and 9 once each. Write one odd and one even number.","Add two odd numbers, for example 7 + 5 and 13 + 9. What do you notice? Test one more pair."]},{"type":"tip","text":"Answers for the teacher: 1) Even. It ends in 0 and can be made into pairs.; 2) for example 479 (odd) and 794 (even); 3) The answer is even each time."}]}$j$::jsonb, $t$advanced$t$, 10, array[$t$text$t$]::text[], false, 1, array[$t$WN.04$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole numbers: odd and even numbers (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L04$t$, 6, $t$check$t$, $t$formative_questions$t$, $t$Questions to ask: Odd and even numbers to 1 000$t$, $t$Oral questions that show quickly who understands.$t$, $j${"blocks":[{"type":"numbered","items":["Is 287 odd or even?","Is 540 odd or even?","Write an even number between 990 and 1 000."]},{"type":"tip","text":"Answers for the teacher: 1) odd; 2) even; 3) for example 996"},{"type":"tip","text":"Ask learners to answer on their fingers, a slate or a scrap of paper so you can see everyone."}]}$j$::jsonb, $t$standard$t$, 5, array[$t$teacher_led$t$]::text[], false, 1, array[$t$WN.04$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole numbers: odd and even numbers (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L05$t$, 1, $t$explain$t$, $t$teacher_explanation$t$, $t$Which digit decides?$t$, $t$The rounding rule for 10, 100 and 1 000.$t$, $j${"blocks":[{"type":"tip","text":"Funda360 example. It is not taken from the DBE documents."},{"type":"steps","items":["To round to the nearest 10 look at the ones digit. To the nearest 100 look at the tens digit. To the nearest 1 000 look at the hundreds digit.","If that digit is 5 or more, round up. If it is 4 or less, the number stays and the digits to the right become 0.","4 382 to the nearest 10 is 4 380. To the nearest 100 it is 4 400. To the nearest 1 000 it is 4 000.","4 350 is exactly halfway between 4 300 and 4 400. Halfway numbers round up, so it is 4 400.","9 960 to the nearest 100: the tens digit is 6, so round up to 10 000."]}]}$j$::jsonb, $t$standard$t$, 10, array[$t$text$t$,$t$teacher_led$t$]::text[], false, 1, array[$t$WN.06$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole numbers: rounding to the nearest 10, 100 and 1 000 (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L05$t$, 2, $t$show$t$, $t$diagram$t$, $t$Rounding on a number line$t$, $t$Where the halfway point is.$t$, $j${"blocks":[{"type":"paragraph","text":"Draw a number line from 4 300 to 4 400 and mark 4 350 in the middle."},{"type":"table","headers":["4 300","4 349","4 350","4 400"],"rows":[["stays 4 300","rounds down to 4 300","halfway: rounds up to 4 400","stays 4 400"]]}],"alt_text":"A number line from 4 300 to 4 400 with the halfway point 4 350 marked. Numbers below 4 350 round down to 4 300 and 4 350 or more round up to 4 400."}$j$::jsonb, $t$standard$t$, 5, array[$t$visual$t$,$t$teacher_led$t$]::text[], false, 1, array[$t$WN.06$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole numbers: rounding to the nearest 10, 100 and 1 000 (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L05$t$, 3, $t$try$t$, $t$classroom_activity$t$, $t$Walk to the nearest hundred$t$, $t$Learners walk to the nearest hundred on a number line on the floor.$t$, $j${"blocks":[{"type":"steps","items":["Chalk a line on the floor and mark 4 300, 4 400 and 4 500 with cards.","Call a number, for example 4 462.","Learners walk to the hundred it is nearest to and say why.","Repeat with halfway numbers such as 4 350."]}]}$j$::jsonb, $t$standard$t$, 15, array[$t$practical$t$,$t$teacher_led$t$]::text[], false, 1, array[$t$WN.06$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole numbers: rounding to the nearest 10, 100 and 1 000 (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L05$t$, 4, $t$practise$t$, $t$exercise$t$, $t$Practice set: rounding$t$, $t$Eight questions.$t$, $j${"blocks":[{"type":"numbered","items":["Round 4 382 to the nearest 10.","Round 4 382 to the nearest 100.","Round 4 382 to the nearest 1 000.","Round 7 650 to the nearest 100.","Round 7 649 to the nearest 100.","Round 2 500 to the nearest 1 000.","Round 9 960 to the nearest 100.","Round 6 105 to the nearest 10."]},{"type":"tip","text":"Answers for the teacher: 1) 4 380; 2) 4 400; 3) 4 000; 4) 7 700; 5) 7 600; 6) 3 000; 7) 10 000; 8) 6 110"}]}$j$::jsonb, $t$standard$t$, 15, array[$t$text$t$]::text[], false, 1, array[$t$WN.06$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole numbers: rounding to the nearest 10, 100 and 1 000 (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L05$t$, 5, $t$support$t$, $t$remediation$t$, $t$Support: rounding to the nearest 10 on a 0 to 100 line$t$, $t$Round to the nearest 10 with numbers to 100 first.$t$, $j${"blocks":[{"type":"steps","items":["Draw a number line from 0 to 100 with a mark at every 10.","Show 47. Which tens is it between? Which is it closer to?","Learners place a counter on the line and say the rounded number.","Repeat with 63, 85 and 95. Then move on to hundreds."]}]}$j$::jsonb, $t$foundational$t$, 15, array[$t$practical$t$,$t$teacher_led$t$]::text[], false, 1, array[$t$WN.06$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole numbers: rounding to the nearest 10, 100 and 1 000 (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L05$t$, 6, $t$challenge$t$, $t$extension$t$, $t$Challenge: rounding puzzles$t$, $t$Finding numbers that fit and spotting a common mistake.$t$, $j${"blocks":[{"type":"numbered","items":["A number rounds to 4 900 to the nearest 100 and to 5 000 to the nearest 1 000. What could it be?","Sipho says 2 449 rounds to 2 500 to the nearest 100 because 49 rounds up to 50. What is his mistake?","Write three numbers that round to 3 600 to the nearest 100."]},{"type":"tip","text":"Answers for the teacher: 1) any number from 4 850 to 4 949, for example 4 900; 2) He rounded twice. The tens digit is 4, so 2 449 rounds to 2 400.; 3) for example 3 550, 3 600 and 3 649"}]}$j$::jsonb, $t$advanced$t$, 15, array[$t$text$t$]::text[], false, 1, array[$t$WN.06$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole numbers: rounding to the nearest 10, 100 and 1 000 (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L05$t$, 7, $t$check$t$, $t$formative_questions$t$, $t$Questions to ask: Rounding to the nearest 10, 100 and 1 000$t$, $t$Oral questions that show quickly who understands.$t$, $j${"blocks":[{"type":"numbered","items":["Which digit do you look at to round to the nearest 100?","Round 5 280 to the nearest 100.","Round 3 499 to the nearest 1 000."]},{"type":"tip","text":"Answers for the teacher: 1) the tens digit; 2) 5 300; 3) 3 000"},{"type":"tip","text":"Ask learners to answer on their fingers, a slate or a scrap of paper so you can see everyone."}]}$j$::jsonb, $t$standard$t$, 5, array[$t$teacher_led$t$]::text[], false, 1, array[$t$WN.06$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole numbers: rounding to the nearest 10, 100 and 1 000 (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L06$t$, 1, $t$explain$t$, $t$teacher_explanation$t$, $t$From a story to a number sentence$t$, $t$Three stories written as number sentences.$t$, $j${"blocks":[{"type":"tip","text":"Funda360 example. It is not taken from the DBE documents."},{"type":"steps","items":["Read the story and find the numbers. Decide what is unknown and use a box for it.","Naledi has 24 marbles and wins 15 more: 24 + 15 = □. Inspection: the box is 39.","There are 7 boxes with 6 eggs in each: 7 × 6 = □. The box is 42.","A learner had 50 stickers and gave some away. 32 are left: 50 − □ = 32. Think: what do I take from 50 to get 32? The box is 18.","Inspection means looking at the sentence and thinking what number fits, for example □ + 8 = 20 so the box is 12."]}]}$j$::jsonb, $t$standard$t$, 10, array[$t$text$t$,$t$teacher_led$t$]::text[], false, 1, array[$t$NS.01$t$,$t$NS.02$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Number sentences: writing number sentences and solving by inspection (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L06$t$, 2, $t$try$t$, $t$group_activity$t$, $t$Act out the story$t$, $t$Learners act out a short story with counters, then write the sentence.$t$, $j${"blocks":[{"type":"steps","items":["Give each group a short story card, for example: 18 learners on a bus, 9 more get on.","The group acts it out with counters.","They write the number sentence with a box for the unknown.","They swap with another group, who solve it by inspection."]}]}$j$::jsonb, $t$standard$t$, 15, array[$t$practical$t$]::text[], false, 1, array[$t$NS.01$t$,$t$NS.02$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Number sentences: writing number sentences and solving by inspection (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L06$t$, 3, $t$practise$t$, $t$exercise$t$, $t$Practice set: write and solve$t$, $t$Five stories and sentences.$t$, $j${"blocks":[{"type":"numbered","items":["Lindiwe has 45 beads and gets 28 more. Write a number sentence and solve it.","There were 90 learners on a bus. Some got off and 64 are left. Write a number sentence and solve it.","A hall has 8 rows of 9 chairs. Write a number sentence and solve it.","Complete by inspection: □ + 17 = 40","Complete by inspection: 100 − □ = 35"]},{"type":"tip","text":"Answers for the teacher: 1) 45 + 28 = 73; 2) 90 − □ = 64, the box is 26; 3) 8 × 9 = 72; 4) 23; 5) 65"}]}$j$::jsonb, $t$standard$t$, 15, array[$t$text$t$]::text[], false, 1, array[$t$NS.01$t$,$t$NS.02$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Number sentences: writing number sentences and solving by inspection (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L06$t$, 4, $t$support$t$, $t$remediation$t$, $t$Support: stories with small numbers$t$, $t$Act out stories with counters before writing.$t$, $j${"blocks":[{"type":"steps","items":["Use stories with numbers to 20, for example: 6 children, 4 more come.","Act out the story with counters.","Say the story, then write the number sentence together.","Move the unknown to a different place: 6 + □ = 10."]}]}$j$::jsonb, $t$foundational$t$, 15, array[$t$practical$t$,$t$teacher_led$t$]::text[], false, 1, array[$t$NS.01$t$,$t$NS.02$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Number sentences: writing number sentences and solving by inspection (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L06$t$, 5, $t$challenge$t$, $t$extension$t$, $t$Challenge: two sentences, one story$t$, $t$Seeing how number sentences are connected.$t$, $j${"blocks":[{"type":"numbered","items":["Write your own story for 6 × □ = 54 and solve it.","18 + □ = 30 and 30 − 18 = □ describe the same story. Explain why."]},{"type":"tip","text":"Answers for the teacher: 1) for example 6 bags with the same number of oranges, 54 altogether: the box is 9; 2) They are linked: adding on from 18 to reach 30 and taking 18 away from 30 both find the missing 12."}]}$j$::jsonb, $t$advanced$t$, 10, array[$t$text$t$]::text[], false, 1, array[$t$NS.01$t$,$t$NS.02$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Number sentences: writing number sentences and solving by inspection (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L06$t$, 6, $t$check$t$, $t$formative_questions$t$, $t$Questions to ask: Writing and solving number sentences$t$, $t$Oral questions that show quickly who understands.$t$, $j${"blocks":[{"type":"numbered","items":["Write a number sentence: 12 sweets and 5 more.","□ + 8 = 20. What is the box?","40 − □ = 25. What is the box?"]},{"type":"tip","text":"Answers for the teacher: 1) 12 + 5 = □; 2) 12; 3) 15"},{"type":"tip","text":"Ask learners to answer on their fingers, a slate or a scrap of paper so you can see everyone."}]}$j$::jsonb, $t$standard$t$, 5, array[$t$teacher_led$t$]::text[], false, 1, array[$t$NS.01$t$,$t$NS.02$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Number sentences: writing number sentences and solving by inspection (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L07$t$, 1, $t$explain$t$, $t$teacher_explanation$t$, $t$Guess, test, improve$t$, $t$Trial and improvement with a recording table.$t$, $j${"blocks":[{"type":"tip","text":"Funda360 example. It is not taken from the DBE documents."},{"type":"paragraph","text":"When the answer is not obvious, make a sensible guess, test it, and use the result to make a better guess."},{"type":"steps","items":["Write the sentence: □ + 38 = 91.","Guess 50: 50 + 38 = 88. Too small, so try a bigger number.","Guess 55: 55 + 38 = 93. Too big, so try a smaller number.","Guess 53: 53 + 38 = 91. Correct.","Check by substitution: put 53 in the box. 53 + 38 = 91 and 91 = 91, so the solution is right. If we try 52: 52 + 38 = 90, and 90 is not 91, so 52 is not the solution."]}]}$j$::jsonb, $t$standard$t$, 10, array[$t$text$t$,$t$teacher_led$t$]::text[], false, 1, array[$t$NS.03$t$,$t$NS.04$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Number sentences: trial and improvement, checking by substitution (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L07$t$, 2, $t$try$t$, $t$group_activity$t$, $t$Guess my number$t$, $t$A game where learners improve their guesses.$t$, $j${"blocks":[{"type":"steps","items":["Write a number sentence with a box on the board, for example 12 × □ = 84.","Groups guess and test, writing each guess in a table.","The first group to reach the answer checks it by substitution.","Ask: how did you decide your next guess?"]}]}$j$::jsonb, $t$standard$t$, 15, array[$t$practical$t$,$t$teacher_led$t$]::text[], false, 1, array[$t$NS.03$t$,$t$NS.04$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Number sentences: trial and improvement, checking by substitution (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L07$t$, 3, $t$practise$t$, $t$exercise$t$, $t$Practice set: trial and improvement$t$, $t$Six questions.$t$, $j${"blocks":[{"type":"numbered","items":["Solve by trial and improvement: 12 × □ = 84","Solve by trial and improvement: □ + 46 = 113","Solve by trial and improvement: □ × 8 = 96","Solve by trial and improvement: 100 − □ = 37","Is 29 the solution of □ + 48 = 77? Check by substitution.","Is 31 the solution of 85 − □ = 56? Check by substitution."]},{"type":"tip","text":"Answers for the teacher: 1) 7; 2) 67; 3) 12; 4) 63; 5) Yes: 29 + 48 = 77; 6) No: 85 − 31 = 54, not 56. The solution is 29"}]}$j$::jsonb, $t$standard$t$, 15, array[$t$text$t$]::text[], false, 1, array[$t$NS.03$t$,$t$NS.04$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Number sentences: trial and improvement, checking by substitution (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L07$t$, 4, $t$support$t$, $t$remediation$t$, $t$Support: trial and improvement with small numbers$t$, $t$Use a recording table and numbers to 50.$t$, $j${"blocks":[{"type":"steps","items":["Draw a table with the columns Guess, Result and Too small or too big.","Use □ + 12 = 30 first.","Guess, write the result, and decide whether to go up or down.","Check the answer by putting it back into the sentence."]}]}$j$::jsonb, $t$foundational$t$, 15, array[$t$practical$t$,$t$teacher_led$t$]::text[], false, 1, array[$t$NS.03$t$,$t$NS.04$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Number sentences: trial and improvement, checking by substitution (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L07$t$, 5, $t$challenge$t$, $t$extension$t$, $t$Challenge: two clues$t$, $t$Reasoning and checking, not harder arithmetic.$t$, $j${"blocks":[{"type":"numbered","items":["Find two numbers that add up to 20 and multiply to give 96.","Mpho says the solution of □ × 6 = 72 is 11. Use substitution to show she is wrong.","Explain how you decide your next guess when a guess is too big."]},{"type":"tip","text":"Answers for the teacher: 1) 12 and 8; 2) 11 × 6 = 66, which is not 72. The solution is 12.; 3) Try a smaller number, and use how far off the result was to choose how much smaller."}]}$j$::jsonb, $t$advanced$t$, 15, array[$t$text$t$]::text[], false, 1, array[$t$NS.03$t$,$t$NS.04$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Number sentences: trial and improvement, checking by substitution (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L07$t$, 6, $t$check$t$, $t$formative_questions$t$, $t$Questions to ask: Trial and improvement, and checking by substitution$t$, $t$Oral questions that show quickly who understands.$t$, $j${"blocks":[{"type":"numbered","items":["□ + 25 = 60. Is 30 too big or too small?","Check by substitution: is 8 the solution of 7 × □ = 54?","What do you do after a guess is too big?"]},{"type":"tip","text":"Answers for the teacher: 1) too small; 2) No: 7 × 8 = 56; 3) try a smaller number"},{"type":"tip","text":"Ask learners to answer on their fingers, a slate or a scrap of paper so you can see everyone."}]}$j$::jsonb, $t$standard$t$, 5, array[$t$teacher_led$t$]::text[], false, 1, array[$t$NS.03$t$,$t$NS.04$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Number sentences: trial and improvement, checking by substitution (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L08$t$, 1, $t$explain$t$, $t$teacher_explanation$t$, $t$Commutative property: does the order matter?$t$, $t$Order and addition or multiplication.$t$, $j${"blocks":[{"type":"tip","text":"Funda360 example. It is not taken from the DBE documents."},{"type":"steps","items":["Show 8 counters and 5 counters. Count them as 8 + 5, then as 5 + 8. The total is the same, 13.","Make an array of 4 rows of 6, then turn it. 4 × 6 and 6 × 4 are both 24.","Try subtraction: 8 − 5 = 3, but 5 − 8 cannot be done with whole numbers. The order does matter for subtraction.","This idea is called the commutative property. It helps us swap numbers to make a calculation easier."]}]}$j$::jsonb, $t$standard$t$, 10, array[$t$text$t$,$t$teacher_led$t$,$t$practical$t$]::text[], false, 1, array[$t$NS.05$t$,$t$NS.06$t$,$t$NS.07$t$,$t$NS.08$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Number sentences: commutative, associative and distributive properties; additive property of 0 (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L08$t$, 2, $t$explain$t$, $t$teacher_explanation$t$, $t$Associative property: does the grouping matter?$t$, $t$Grouping and addition or multiplication.$t$, $j${"blocks":[{"type":"steps","items":["Add three numbers: (14 + 6) + 9 and 14 + (6 + 9). Both give 29. Grouping 14 + 6 first makes a friendly 20.","Multiply three numbers: (2 × 5) × 7 and 2 × (5 × 7). Both give 70.","Try subtraction: (10 − 4) − 3 = 3 but 10 − (4 − 3) = 9. The grouping does matter for subtraction.","This idea is called the associative property. It lets us choose which two numbers to combine first."]}]}$j$::jsonb, $t$standard$t$, 10, array[$t$text$t$,$t$teacher_led$t$]::text[], false, 1, array[$t$NS.05$t$,$t$NS.06$t$,$t$NS.07$t$,$t$NS.08$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Number sentences: commutative, associative and distributive properties; additive property of 0 (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L08$t$, 3, $t$explain$t$, $t$teacher_explanation$t$, $t$Distributive property: breaking a number into parts$t$, $t$Multiplying each part.$t$, $j${"blocks":[{"type":"steps","items":["Break 12 into 10 + 2. Then 7 × 12 = 7 × 10 + 7 × 2 = 70 + 14 = 84.","Draw a rectangle 7 by 12 and cut it into a 7 by 10 part and a 7 by 2 part. The two areas add to the whole: 70 + 14 = 84.","Try 6 × 15 = 6 × 10 + 6 × 5 = 60 + 30 = 90.","This idea is called the distributive property. It is the reason breaking numbers down works when we multiply."]}]}$j$::jsonb, $t$standard$t$, 10, array[$t$text$t$,$t$teacher_led$t$]::text[], false, 1, array[$t$NS.05$t$,$t$NS.06$t$,$t$NS.07$t$,$t$NS.08$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Number sentences: commutative, associative and distributive properties; additive property of 0 (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L08$t$, 4, $t$explain$t$, $t$teacher_explanation$t$, $t$The additive property of zero$t$, $t$What adding 0 does.$t$, $j${"blocks":[{"type":"steps","items":["Show 9 counters and add 0 counters. There are still 9. So 9 + 0 = 9 and 0 + 9 = 9.","This works for any number: 4 382 + 0 = 4 382. Adding 0 does not change the number.","Subtracting 0 also leaves a number unchanged: 4 382 − 0 = 4 382.","Careful: the zero in 4 058 is a place holder that shows there are no hundreds. That is a different job from adding 0."]}]}$j$::jsonb, $t$standard$t$, 8, array[$t$text$t$,$t$teacher_led$t$]::text[], false, 1, array[$t$NS.05$t$,$t$NS.06$t$,$t$NS.07$t$,$t$NS.08$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Number sentences: commutative, associative and distributive properties; additive property of 0 (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L08$t$, 5, $t$try$t$, $t$classroom_activity$t$, $t$Counters and arrays$t$, $t$Learners test each property with counters.$t$, $j${"blocks":[{"type":"steps","items":["Give each pair 30 counters.","Make 6 rows of 4 counters, then 4 rows of 6. Are the totals equal?","Group three piles in two different ways and add. Do the totals change?","Try the same with subtraction. What is different?","Write what you noticed in your own words."]}]}$j$::jsonb, $t$standard$t$, 15, array[$t$practical$t$,$t$teacher_led$t$]::text[], false, 1, array[$t$NS.05$t$,$t$NS.06$t$,$t$NS.07$t$,$t$NS.08$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Number sentences: commutative, associative and distributive properties; additive property of 0 (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L08$t$, 6, $t$practise$t$, $t$exercise$t$, $t$Practice set: properties$t$, $t$Six questions.$t$, $j${"blocks":[{"type":"numbered","items":["Fill in the box: 38 + 27 = 27 + □","Fill in the box: (14 + 6) + 9 = 14 + (□ + 9)","Fill in the box: 7 × 12 = 7 × 10 + 7 × □","Fill in the box: 4 658 + 0 = □","True or false: 9 − 4 = 4 − 9","Use the distributive property: 6 × 15 = 6 × 10 + 6 × □ = □"]},{"type":"tip","text":"Answers for the teacher: 1) 38; 2) 6; 3) 2; 4) 4 658; 5) false: the order matters for subtraction; 6) 5 and 90"}]}$j$::jsonb, $t$standard$t$, 15, array[$t$text$t$]::text[], false, 1, array[$t$NS.05$t$,$t$NS.06$t$,$t$NS.07$t$,$t$NS.08$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Number sentences: commutative, associative and distributive properties; additive property of 0 (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L08$t$, 7, $t$support$t$, $t$remediation$t$, $t$Support: the properties on a counter mat$t$, $t$Show each property with counters on a paper mat.$t$, $j${"blocks":[{"type":"steps","items":["Draw two boxes on a paper mat. Put 3 counters in one and 5 in the other.","Count all the counters. Swap the boxes. Count again. What did not change?","Add a third box and group the counters in two ways.","Put 0 counters in one box. What happens to the total?"]}]}$j$::jsonb, $t$foundational$t$, 15, array[$t$practical$t$,$t$teacher_led$t$]::text[], false, 1, array[$t$NS.05$t$,$t$NS.06$t$,$t$NS.07$t$,$t$NS.08$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Number sentences: commutative, associative and distributive properties; additive property of 0 (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L08$t$, 8, $t$challenge$t$, $t$extension$t$, $t$Challenge: use properties to help you$t$, $t$Choosing a property to make a calculation easier.$t$, $j${"blocks":[{"type":"numbered","items":["Work out 2 × 17 × 5 in your head. Which numbers did you multiply first, and why?","Explain why (20 − 8) − 3 and 20 − (8 − 3) give different answers.","Which is always true for whole numbers? (a) a − b = b − a  (b) a + b = b + a"]},{"type":"tip","text":"Answers for the teacher: 1) 170. Multiply 2 × 5 = 10 first, then 10 × 17.; 2) The first is 9 and the second is 15. Subtraction is not associative.; 3) (b)"}]}$j$::jsonb, $t$advanced$t$, 15, array[$t$text$t$]::text[], false, 1, array[$t$NS.05$t$,$t$NS.06$t$,$t$NS.07$t$,$t$NS.08$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Number sentences: commutative, associative and distributive properties; additive property of 0 (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L08$t$, 9, $t$check$t$, $t$formative_questions$t$, $t$Questions to ask: Properties of operations: order, grouping, parts and zero$t$, $t$Oral questions that show quickly who understands.$t$, $j${"blocks":[{"type":"numbered","items":["Is 6 × 4 the same as 4 × 6?","What is 357 + 0?","Does the order matter for 10 − 3 and 3 − 10?"]},{"type":"tip","text":"Answers for the teacher: 1) yes; 2) 357; 3) yes"},{"type":"tip","text":"Ask learners to answer on their fingers, a slate or a scrap of paper so you can see everyone."}]}$j$::jsonb, $t$standard$t$, 5, array[$t$teacher_led$t$]::text[], false, 1, array[$t$NS.05$t$,$t$NS.06$t$,$t$NS.07$t$,$t$NS.08$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Number sentences: commutative, associative and distributive properties; additive property of 0 (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L09$t$, 1, $t$explain$t$, $t$teacher_explanation$t$, $t$Breaking down and building up$t$, $t$Worked through for addition and subtraction.$t$, $j${"blocks":[{"type":"tip","text":"Funda360 example. It is not taken from the DBE documents."},{"type":"steps","items":["Breaking down to add: 3 746 + 2 589. Break 2 589 into 2 000 + 500 + 80 + 9.","3 746 + 2 000 = 5 746; + 500 = 6 246; + 80 = 6 326; + 9 = 6 335.","Breaking down to subtract: 6 335 − 2 589: 6 335 − 2 000 = 4 335; − 500 = 3 835; − 80 = 3 755; − 9 = 3 746.","Building up to subtract: how far from 2 589 to 6 335? Jump 11 to 2 600, 400 to 3 000, 3 000 to 6 000, then 335 to 6 335. The jumps add up to 3746, so the difference is 3 746.","Ask after every step: what did we add or take away, and why?"]}]}$j$::jsonb, $t$standard$t$, 10, array[$t$text$t$,$t$teacher_led$t$]::text[], false, 1, array[$t$AS.01$t$,$t$AS.03$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole-number addition and subtraction: four-digit numbers, building up and breaking down (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L09$t$, 2, $t$show$t$, $t$diagram$t$, $t$Jumps: building up from 2 589 to 6 335$t$, $t$The building-up jumps on a number line.$t$, $j${"blocks":[{"type":"table","headers":["Start","+11","+400","+3 000","+335"],"rows":[["2 589","2 600","3 000","6 000","6 335"]]}],"alt_text":"A number line from 2 589 to 6 335 with four jumps: plus 11 to 2 600, plus 400 to 3 000, plus 3 000 to 6 000 and plus 335 to 6 335."}$j$::jsonb, $t$standard$t$, 5, array[$t$visual$t$,$t$teacher_led$t$]::text[], false, 1, array[$t$AS.01$t$,$t$AS.03$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole-number addition and subtraction: four-digit numbers, building up and breaking down (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L09$t$, 3, $t$try$t$, $t$classroom_activity$t$, $t$Break it down together$t$, $t$Pairs solve one sum two ways and compare.$t$, $j${"blocks":[{"type":"steps","items":["Give each pair a sum on a card, for example 4 218 + 3 475.","One learner breaks the second number down. The other builds up in jumps.","They compare answers. If different, they find the step where they differ."]}]}$j$::jsonb, $t$standard$t$, 15, array[$t$practical$t$,$t$teacher_led$t$]::text[], false, 1, array[$t$AS.01$t$,$t$AS.03$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole-number addition and subtraction: four-digit numbers, building up and breaking down (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L09$t$, 4, $t$practise$t$, $t$exercise$t$, $t$Practice set: add and subtract$t$, $t$Six calculations.$t$, $j${"blocks":[{"type":"numbered","items":["4 218 + 3 475","5 862 + 1 749","6 405 − 2 138","8 000 − 3 456","7 391 − 4 285","2 849 + 5 372"]},{"type":"tip","text":"Answers for the teacher: 1) 7 693; 2) 7 611; 3) 4 267; 4) 4 544; 5) 3 106; 6) 8 221"}]}$j$::jsonb, $t$standard$t$, 15, array[$t$text$t$]::text[], false, 1, array[$t$AS.01$t$,$t$AS.03$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole-number addition and subtraction: four-digit numbers, building up and breaking down (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L09$t$, 5, $t$support$t$, $t$remediation$t$, $t$Support: three-digit numbers with place value cards$t$, $t$Add and subtract numbers to 999 with place value cards.$t$, $j${"blocks":[{"type":"steps","items":["Give pairs place value cards for hundreds, tens and ones.","Build 345 and 128. Add the hundreds, then the tens, then the ones.","Write each step. Then do a subtraction such as 473 − 128 by taking away hundreds, tens and ones.","Move to four-digit numbers when secure."]}]}$j$::jsonb, $t$foundational$t$, 15, array[$t$practical$t$,$t$teacher_led$t$]::text[], false, 1, array[$t$AS.01$t$,$t$AS.03$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole-number addition and subtraction: four-digit numbers, building up and breaking down (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L09$t$, 6, $t$challenge$t$, $t$extension$t$, $t$Challenge: find the mistake$t$, $t$Checking a method and using inverse thinking.$t$, $j${"blocks":[{"type":"numbered","items":["Sam added 4 365 + 2 481 like this: 6 365, + 400 = 6 765, + 8 = 6 773, + 1 = 6 774. What went wrong? What is the right answer?","Two numbers add up to 9 000. One is 5 478. What is the other? Show your strategy."]},{"type":"tip","text":"Answers for the teacher: 1) He added 8 instead of 80. The right answer is 6 846.; 2) 3 522"}]}$j$::jsonb, $t$advanced$t$, 15, array[$t$text$t$]::text[], false, 1, array[$t$AS.01$t$,$t$AS.03$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole-number addition and subtraction: four-digit numbers, building up and breaking down (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L09$t$, 7, $t$check$t$, $t$formative_questions$t$, $t$Questions to ask: Adding and subtracting by building up and breaking down$t$, $t$Oral questions that show quickly who understands.$t$, $j${"blocks":[{"type":"numbered","items":["Break 2 589 into thousands, hundreds, tens and ones.","What is 4 000 + 3 000?","From 2 589, how far to the next hundred?"]},{"type":"tip","text":"Answers for the teacher: 1) 2 000 + 500 + 80 + 9; 2) 7 000; 3) 11"},{"type":"tip","text":"Ask learners to answer on their fingers, a slate or a scrap of paper so you can see everyone."}]}$j$::jsonb, $t$standard$t$, 5, array[$t$teacher_led$t$]::text[], false, 1, array[$t$AS.01$t$,$t$AS.03$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole-number addition and subtraction: four-digit numbers, building up and breaking down (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L10$t$, 1, $t$explain$t$, $t$teacher_explanation$t$, $t$Jumping and estimating$t$, $t$Number-line jumps and rounding to estimate.$t$, $j${"blocks":[{"type":"tip","text":"Funda360 example. It is not taken from the DBE documents."},{"type":"steps","items":["Number line to add: 4 250 + 1 375. Jump 1 000 to 5 250, 300 to 5 550, 70 to 5 620, 5 to 5 625.","Number line to subtract: 7 400 − 2 650. Jump back 2 000 to 5 400, 600 to 4 800, 50 to 4 750.","Estimate by rounding to the nearest 1 000: 4 876 + 3 125 is about 5 000 + 3 000 = 8 000. The exact answer is 8 001, which is close.","Use the estimate to ask: is my answer sensible? If the estimate is 8 000 and my answer is 5 000, I must check my work."]}]}$j$::jsonb, $t$standard$t$, 10, array[$t$text$t$,$t$teacher_led$t$]::text[], false, 1, array[$t$AS.02$t$,$t$AS.04$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole-number addition and subtraction: number lines and estimation (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L10$t$, 2, $t$show$t$, $t$diagram$t$, $t$Number line: 4 250 + 1 375$t$, $t$The jumps drawn on the board.$t$, $j${"blocks":[{"type":"table","headers":["Start","+1 000","+300","+70","+5"],"rows":[["4 250","5 250","5 550","5 620","5 625"]]}],"alt_text":"A number line starting at 4 250 with four jumps: plus 1 000 to 5 250, plus 300 to 5 550, plus 70 to 5 620 and plus 5 to 5 625."}$j$::jsonb, $t$standard$t$, 5, array[$t$visual$t$,$t$teacher_led$t$]::text[], false, 1, array[$t$AS.02$t$,$t$AS.04$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole-number addition and subtraction: number lines and estimation (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L10$t$, 3, $t$try$t$, $t$classroom_activity$t$, $t$Estimate, then jump$t$, $t$Pairs estimate, calculate on a number line and compare.$t$, $j${"blocks":[{"type":"steps","items":["Write a sum on the board.","Each pair writes an estimate on a slate or paper.","They calculate with jumps on an empty number line.","They compare the answer with the estimate and say if it is sensible."]}]}$j$::jsonb, $t$standard$t$, 15, array[$t$practical$t$,$t$teacher_led$t$]::text[], false, 1, array[$t$AS.02$t$,$t$AS.04$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole-number addition and subtraction: number lines and estimation (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L10$t$, 4, $t$practise$t$, $t$exercise$t$, $t$Practice set: number lines and estimating$t$, $t$Six questions.$t$, $j${"blocks":[{"type":"numbered","items":["Use a number line: 4 250 + 1 375","Use a number line: 7 400 − 2 650","Use a number line: 3 800 + 2 460","Use a number line: 9 100 − 4 570","Estimate 4 876 + 3 125 by rounding to the nearest 1 000.","Estimate 7 912 − 2 088 by rounding to the nearest 1 000."]},{"type":"tip","text":"Answers for the teacher: 1) 5 625; 2) 4 750; 3) 6 260; 4) 4 530; 5) 5 000 + 3 000 = 8 000; 6) 8 000 − 2 000 = 6 000"}]}$j$::jsonb, $t$standard$t$, 15, array[$t$text$t$]::text[], false, 1, array[$t$AS.02$t$,$t$AS.04$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole-number addition and subtraction: number lines and estimation (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L10$t$, 5, $t$support$t$, $t$remediation$t$, $t$Support: number lines to 1 000$t$, $t$Jump on a number line with numbers to 1 000.$t$, $j${"blocks":[{"type":"steps","items":["Draw an empty number line and write 250 at the start.","Add 130 with jumps: 100 then 30. Write each landing number.","Subtract 120 from 400 with jumps back.","Estimate each answer to the nearest 100 before you calculate."]}]}$j$::jsonb, $t$foundational$t$, 15, array[$t$practical$t$,$t$teacher_led$t$]::text[], false, 1, array[$t$AS.02$t$,$t$AS.04$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole-number addition and subtraction: number lines and estimation (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L10$t$, 6, $t$challenge$t$, $t$extension$t$, $t$Challenge: is the answer sensible?$t$, $t$Using an estimate to catch a mistake.$t$, $j${"blocks":[{"type":"numbered","items":["Kagiso says 3 962 + 2 047 = 5 009. His estimate was 4 000 + 2 000 = 6 000. Is his answer sensible? What is the correct answer?","When is an estimate good enough, and when do we need the exact answer? Give one example of each."]},{"type":"tip","text":"Answers for the teacher: 1) No. The estimate is about 6 000 and the answer is 6 009.; 2) Estimates check or give a quick idea; exact answers are needed for example when paying or measuring exactly."}]}$j$::jsonb, $t$advanced$t$, 15, array[$t$text$t$]::text[], false, 1, array[$t$AS.02$t$,$t$AS.04$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole-number addition and subtraction: number lines and estimation (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L10$t$, 7, $t$check$t$, $t$formative_questions$t$, $t$Questions to ask: Number lines and estimation$t$, $t$Oral questions that show quickly who understands.$t$, $j${"blocks":[{"type":"numbered","items":["Estimate 2 980 + 4 020 to the nearest 1 000.","Jump: 3 000 + 450. What do you land on?","Is 5 000 a sensible answer for 3 962 + 2 047?"]},{"type":"tip","text":"Answers for the teacher: 1) 7 000; 2) 3 450; 3) no, it should be about 6 000"},{"type":"tip","text":"Ask learners to answer on their fingers, a slate or a scrap of paper so you can see everyone."}]}$j$::jsonb, $t$standard$t$, 5, array[$t$teacher_led$t$]::text[], false, 1, array[$t$AS.02$t$,$t$AS.04$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole-number addition and subtraction: number lines and estimation (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L11$t$, 1, $t$explain$t$, $t$teacher_explanation$t$, $t$Make it friendly, then fix it$t$, $t$Rounding and compensating, and the inverse check.$t$, $j${"blocks":[{"type":"tip","text":"Funda360 example. It is not taken from the DBE documents."},{"type":"steps","items":["4 387 + 1 998: 1 998 is 2 less than 2 000. Add 2 000: 6 387. We added 2 too many, so take 2 away: 6 385.","6 502 − 1 999: take away 2 000 instead: 4 502. We took away 1 too many, so add 1 back: 4 503.","Check with the inverse. Subtraction is undone by addition: 4 503 + 1 999 = 6 502, so 6 502 − 1 999 = 4 503 is correct.","Addition is undone by subtraction: 6 385 − 1 998 = 4 387, so 4 387 + 1 998 = 6 385."]}]}$j$::jsonb, $t$standard$t$, 10, array[$t$text$t$,$t$teacher_led$t$]::text[], false, 1, array[$t$AS.05$t$,$t$AS.06$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole-number addition and subtraction: rounding and compensating, inverse operations (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L11$t$, 2, $t$try$t$, $t$group_activity$t$, $t$Friendly numbers$t$, $t$Groups find a friendly number for each sum and explain the fix.$t$, $j${"blocks":[{"type":"steps","items":["Write sums with numbers close to a round number, for example 3 475 + 1 997.","Groups choose the friendly number and write the fix.","Groups check with the inverse operation.","Share one method with the class."]}]}$j$::jsonb, $t$standard$t$, 15, array[$t$practical$t$,$t$teacher_led$t$]::text[], false, 1, array[$t$AS.05$t$,$t$AS.06$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole-number addition and subtraction: rounding and compensating, inverse operations (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L11$t$, 3, $t$practise$t$, $t$exercise$t$, $t$Practice set: compensating and checking$t$, $t$Six questions.$t$, $j${"blocks":[{"type":"numbered","items":["4 387 + 1 998 by compensating","5 246 + 2 999 by compensating","6 502 − 1 999 by compensating","8 130 − 2 998 by compensating","3 475 + 1 997 by compensating","Check 6 385 − 1 998 = 4 387 with addition."]},{"type":"tip","text":"Answers for the teacher: 1) 6 385; 2) 8 245; 3) 4 503; 4) 5 132; 5) 5 472; 6) 4 387 + 1 998 = 6 385"}]}$j$::jsonb, $t$standard$t$, 15, array[$t$text$t$]::text[], false, 1, array[$t$AS.05$t$,$t$AS.06$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole-number addition and subtraction: rounding and compensating, inverse operations (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L11$t$, 4, $t$support$t$, $t$remediation$t$, $t$Support: compensating with small numbers$t$, $t$Practise adding 9 and 10 or taking away 9 and 10.$t$, $j${"blocks":[{"type":"steps","items":["Draw a number line from 40 to 80.","Add 9 to 46 by adding 10 and taking 1 back. Show the jumps.","Take 19 from 62 by taking 20 and adding 1.","Explain each fix in a sentence."]}]}$j$::jsonb, $t$foundational$t$, 15, array[$t$practical$t$,$t$teacher_led$t$]::text[], false, 1, array[$t$AS.05$t$,$t$AS.06$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole-number addition and subtraction: rounding and compensating, inverse operations (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L11$t$, 5, $t$challenge$t$, $t$extension$t$, $t$Challenge: choose and explain$t$, $t$Choosing between strategies.$t$, $j${"blocks":[{"type":"numbered","items":["Why do we take 2 away after adding 2 000 to 4 387 to add 1 998?","Which strategy would you choose for 6 000 − 2 998, and which for 6 347 − 2 340? Explain.","A number was taken from 8 000 and 4 567 was left. Use an inverse operation to find the number."]},{"type":"tip","text":"Answers for the teacher: 1) Because 1 998 is 2 less than 2 000, so adding 2 000 adds 2 too many.; 2) 6 000 − 2 998: compensating (take 3 000, add 2) = 3 002. 6 347 − 2 340: breaking down is simple = 4 007.; 3) 3 433"}]}$j$::jsonb, $t$advanced$t$, 15, array[$t$text$t$]::text[], false, 1, array[$t$AS.05$t$,$t$AS.06$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole-number addition and subtraction: rounding and compensating, inverse operations (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L11$t$, 6, $t$check$t$, $t$formative_questions$t$, $t$Questions to ask: Rounding and compensating, and checking with inverse operations$t$, $t$Oral questions that show quickly who understands.$t$, $j${"blocks":[{"type":"numbered","items":["What is 3 000 − 1 999?","Which operation checks 5 000 + 2 000 = 7 000?","To add 99 you can add 100. What do you do next?"]},{"type":"tip","text":"Answers for the teacher: 1) 1 001; 2) subtraction: 7 000 − 2 000 = 5 000; 3) take 1 away"},{"type":"tip","text":"Ask learners to answer on their fingers, a slate or a scrap of paper so you can see everyone."}]}$j$::jsonb, $t$standard$t$, 5, array[$t$teacher_led$t$]::text[], false, 1, array[$t$AS.05$t$,$t$AS.06$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole-number addition and subtraction: rounding and compensating, inverse operations (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L12$t$, 1, $t$explain$t$, $t$teacher_explanation$t$, $t$Building facts with strategies$t$, $t$Doubling, halving and building up.$t$, $j${"blocks":[{"type":"tip","text":"Funda360 example. It is not taken from the DBE documents."},{"type":"steps","items":["Doubling: ×2 is a double. ×4 is double double. ×8 is double double double. 6 × 4: double 6 is 12, double 12 is 24.","Halving: ×5 is half of ×10. 7 × 5: 7 × 10 = 70 and half of 70 is 35.","Building up: 7 × 8 = 7 × 5 + 7 × 3 = 35 + 21 = 56.","Close to ten: 9 × 7 = 10 × 7 − 7 = 70 − 7 = 63.","Use an array to show that 6 × 8 and 8 × 6 are the same."]}]}$j$::jsonb, $t$standard$t$, 10, array[$t$text$t$,$t$teacher_led$t$]::text[], false, 1, array[$t$MUL.01$t$,$t$MUL.04$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole-number multiplication: one-digit numbers by numbers up to 10 (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L12$t$, 2, $t$show$t$, $t$diagram$t$, $t$Array for 4 × 6$t$, $t$Four rows of six dots.$t$, $j${"blocks":[{"type":"paragraph","text":"Draw four rows with six dots in each row on the board."},{"type":"table","headers":["●","●","●","●","●","●"],"rows":[["●","●","●","●","●","●"],["●","●","●","●","●","●"],["●","●","●","●","●","●"]]},{"type":"tip","text":"Turn the picture on its side to see 6 rows of 4. The total is the same."}],"alt_text":"An array of 4 rows with 6 dots in each row. It shows 4 times 6 equals 24, and turned on its side 6 times 4 equals 24."}$j$::jsonb, $t$standard$t$, 5, array[$t$visual$t$,$t$teacher_led$t$]::text[], false, 1, array[$t$MUL.01$t$,$t$MUL.04$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole-number multiplication: one-digit numbers by numbers up to 10 (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L12$t$, 3, $t$try$t$, $t$classroom_activity$t$, $t$Build arrays with bottle tops$t$, $t$Pairs build arrays for given facts.$t$, $j${"blocks":[{"type":"steps","items":["Give each pair 60 bottle tops.","Build an array for 6 × 8. Count the rows and the tops in each row.","Turn it. Write both facts.","Split the array into two parts to build the fact, for example 6 × 5 and 6 × 3."]}]}$j$::jsonb, $t$standard$t$, 15, array[$t$practical$t$]::text[], false, 1, array[$t$MUL.01$t$,$t$MUL.04$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole-number multiplication: one-digit numbers by numbers up to 10 (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L12$t$, 4, $t$practise$t$, $t$exercise$t$, $t$Practice set: multiplication facts$t$, $t$Eight facts.$t$, $j${"blocks":[{"type":"numbered","items":["6 × 7","8 × 9","4 × 8","7 × 7","9 × 6","5 × 8","Use ×10 and halving: 5 × 6","3 × 9"]},{"type":"tip","text":"Answers for the teacher: 1) 42; 2) 72; 3) 32; 4) 49; 5) 54; 6) 40; 7) 30; 8) 27"}]}$j$::jsonb, $t$standard$t$, 10, array[$t$text$t$]::text[], false, 1, array[$t$MUL.01$t$,$t$MUL.04$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole-number multiplication: one-digit numbers by numbers up to 10 (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L12$t$, 5, $t$support$t$, $t$remediation$t$, $t$Support: build the facts with counters$t$, $t$Build the facts you know first and use them for new ones.$t$, $j${"blocks":[{"type":"steps","items":["Start with facts the learners know: ×2, ×5 and ×10.","Build 3 × 4 with counters in an array.","Use doubling to find 6 × 4.","Write each new fact in a fact table."]}]}$j$::jsonb, $t$foundational$t$, 15, array[$t$practical$t$,$t$teacher_led$t$]::text[], false, 1, array[$t$MUL.01$t$,$t$MUL.04$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole-number multiplication: one-digit numbers by numbers up to 10 (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L12$t$, 6, $t$challenge$t$, $t$extension$t$, $t$Challenge: two ways$t$, $t$Finding a fact in different ways.$t$, $j${"blocks":[{"type":"numbered","items":["Find 7 × 8 in two different ways.","How can you find 9 × 7 using 10 × 7?","Explain with an array why 6 × 8 and 8 × 6 are equal."]},{"type":"tip","text":"Answers for the teacher: 1) for example double double double 7 = 56, or 7 × 5 + 7 × 3 = 56; 2) 10 × 7 = 70, then take away one 7: 63.; 3) Turning the array of 6 rows of 8 gives 8 rows of 6, with the same number of dots."}]}$j$::jsonb, $t$advanced$t$, 15, array[$t$text$t$]::text[], false, 1, array[$t$MUL.01$t$,$t$MUL.04$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole-number multiplication: one-digit numbers by numbers up to 10 (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L12$t$, 7, $t$check$t$, $t$formative_questions$t$, $t$Questions to ask: Multiplying one-digit numbers by numbers up to 10$t$, $t$Oral questions that show quickly who understands.$t$, $j${"blocks":[{"type":"numbered","items":["What is double 14?","What is 6 × 5?","Use 10 × 8 to find 9 × 8."]},{"type":"tip","text":"Answers for the teacher: 1) 28; 2) 30; 3) 80 − 8 = 72"},{"type":"tip","text":"Ask learners to answer on their fingers, a slate or a scrap of paper so you can see everyone."}]}$j$::jsonb, $t$standard$t$, 5, array[$t$teacher_led$t$]::text[], false, 1, array[$t$MUL.01$t$,$t$MUL.04$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole-number multiplication: one-digit numbers by numbers up to 10 (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L13$t$, 1, $t$explain$t$, $t$teacher_explanation$t$, $t$Breaking down and doubling$t$, $t$Three strategies for 34 × 6 and more.$t$, $j${"blocks":[{"type":"tip","text":"Funda360 example. It is not taken from the DBE documents."},{"type":"steps","items":["Breaking down: 34 × 6 = 30 × 6 + 4 × 6 = 180 + 24 = 204.","Doubling and halving: 25 × 4 = double 25 is 50, double 50 is 100. And 125 × 8: 125 × 2 = 250, × 2 = 500, × 2 = 1000.","Split the multiplier: 45 × 6 = (45 × 3) × 2 = 135 × 2 = 270. Multiplying by 3 and then doubling is the same as multiplying by 6.","Estimate first: 47 × 6 is about 50 × 6 = 300. The exact answer is 282, which is close, so it is sensible.","Check with a related fact only when learners know it, for example 6 × 7 = 42."]}]}$j$::jsonb, $t$standard$t$, 10, array[$t$text$t$,$t$teacher_led$t$]::text[], false, 1, array[$t$MUL.02$t$,$t$MUL.04$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole-number multiplication: at least two-digit by one-digit numbers (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L13$t$, 2, $t$try$t$, $t$group_activity$t$, $t$Strategy cards$t$, $t$Groups solve a product with two different strategies.$t$, $j${"blocks":[{"type":"steps","items":["Give each group a card, for example 36 × 5.","They solve it by breaking down and by doubling or halving.","They estimate first and compare the answers.","They explain to another group why both methods give the same result."]}]}$j$::jsonb, $t$standard$t$, 15, array[$t$practical$t$,$t$teacher_led$t$]::text[], false, 1, array[$t$MUL.02$t$,$t$MUL.04$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole-number multiplication: at least two-digit by one-digit numbers (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L13$t$, 3, $t$practise$t$, $t$exercise$t$, $t$Practice set: two-digit by one-digit$t$, $t$Seven questions.$t$, $j${"blocks":[{"type":"numbered","items":["23 × 4","36 × 5","48 × 3","62 × 7","75 × 4","84 × 6","125 × 8"]},{"type":"tip","text":"Answers for the teacher: 1) 92; 2) 180; 3) 144; 4) 434; 5) 300; 6) 504; 7) 1 000"}]}$j$::jsonb, $t$standard$t$, 15, array[$t$text$t$]::text[], false, 1, array[$t$MUL.02$t$,$t$MUL.04$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole-number multiplication: at least two-digit by one-digit numbers (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L13$t$, 4, $t$support$t$, $t$remediation$t$, $t$Support: multiply tens and ones separately$t$, $t$Use counters and a place value mat.$t$, $j${"blocks":[{"type":"steps","items":["Show 23 as 2 tens and 3 ones with counters.","Multiply each part by 4: 2 tens × 4 = 8 tens, 3 ones × 4 = 12 ones.","Add the parts: 80 + 12 = 92.","Repeat with 14 × 3."]}]}$j$::jsonb, $t$foundational$t$, 15, array[$t$practical$t$,$t$teacher_led$t$]::text[], false, 1, array[$t$MUL.02$t$,$t$MUL.04$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole-number multiplication: at least two-digit by one-digit numbers (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L13$t$, 5, $t$challenge$t$, $t$extension$t$, $t$Challenge: use what you know$t$, $t$Using one product to find another.$t$, $j${"blocks":[{"type":"numbered","items":["Use 15 × 6 = 90 to work out 15 × 12 and 30 × 6. Explain why they are the same.","Estimate 38 × 7, then calculate. Is your answer close?","Which is greater, 49 × 6 or 50 × 6? By how much, without calculating both in full?"]},{"type":"tip","text":"Answers for the teacher: 1) 180 and 180. Doubling one number doubles the product, whichever number is doubled.; 2) about 40 × 7 = 280; exact 266. Close.; 3) 50 × 6 by one group of 6: 300 and 294."}]}$j$::jsonb, $t$advanced$t$, 15, array[$t$text$t$]::text[], false, 1, array[$t$MUL.02$t$,$t$MUL.04$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole-number multiplication: at least two-digit by one-digit numbers (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L13$t$, 6, $t$check$t$, $t$formative_questions$t$, $t$Questions to ask: Multiplying a two-digit number by a one-digit number$t$, $t$Oral questions that show quickly who understands.$t$, $j${"blocks":[{"type":"numbered","items":["What is 30 × 4?","Estimate 52 × 3.","What is double 45?"]},{"type":"tip","text":"Answers for the teacher: 1) 120; 2) about 150; 3) 90"},{"type":"tip","text":"Ask learners to answer on their fingers, a slate or a scrap of paper so you can see everyone."}]}$j$::jsonb, $t$standard$t$, 5, array[$t$teacher_led$t$]::text[], false, 1, array[$t$MUL.02$t$,$t$MUL.04$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole-number multiplication: at least two-digit by one-digit numbers (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L14$t$, 1, $t$explain$t$, $t$teacher_explanation$t$, $t$Breaking down the second number$t$, $t$Multiplying by 14 and by 16.$t$, $j${"blocks":[{"type":"tip","text":"Funda360 example. It is not taken from the DBE documents."},{"type":"steps","items":["23 × 14: break 14 into 10 + 4. 23 × 10 = 230 and 23 × 4 = 92. Add: 230 + 92 = 322.","Grid: split both numbers: (20 + 3) × (10 + 4) = 200 + 80 + 30 + 12 = 322.","Doubling and halving: 25 × 16 = 50 × 8 = 100 × 4 = 400.","Estimate first: 38 × 21 is about 40 × 20 = 800. The exact answer is 798, so it is sensible."]}]}$j$::jsonb, $t$standard$t$, 10, array[$t$text$t$,$t$teacher_led$t$]::text[], false, 1, array[$t$MUL.03$t$,$t$MUL.04$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole-number multiplication: at least two-digit by two-digit numbers (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L14$t$, 2, $t$show$t$, $t$worked_example$t$, $t$Grid for 23 × 14$t$, $t$The four parts in a grid.$t$, $j${"blocks":[{"type":"table","headers":["","20","3"],"rows":[["10","200","30"],["4","80","12"]]},{"type":"paragraph","text":"Add the four parts: 200 + 30 + 80 + 12 = 322."}]}$j$::jsonb, $t$standard$t$, 5, array[$t$text$t$,$t$visual$t$]::text[], false, 1, array[$t$MUL.03$t$,$t$MUL.04$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole-number multiplication: at least two-digit by two-digit numbers (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L14$t$, 3, $t$try$t$, $t$group_activity$t$, $t$Grid and double: two ways$t$, $t$Groups solve the same product with a grid and with doubling.$t$, $j${"blocks":[{"type":"steps","items":["Give each group a product, for example 18 × 25.","Solve it with a grid.","Solve it by doubling and halving.","Compare the answers and the number of steps."]}]}$j$::jsonb, $t$standard$t$, 15, array[$t$practical$t$,$t$teacher_led$t$]::text[], false, 1, array[$t$MUL.03$t$,$t$MUL.04$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole-number multiplication: at least two-digit by two-digit numbers (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L14$t$, 4, $t$practise$t$, $t$exercise$t$, $t$Practice set: multiply by a two-digit number$t$, $t$Six questions.$t$, $j${"blocks":[{"type":"numbered","items":["12 × 13","24 × 15","31 × 22","18 × 25","42 × 11","36 × 14"]},{"type":"tip","text":"Answers for the teacher: 1) 156; 2) 360; 3) 682; 4) 450; 5) 462; 6) 504"}]}$j$::jsonb, $t$standard$t$, 15, array[$t$text$t$]::text[], false, 1, array[$t$MUL.03$t$,$t$MUL.04$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole-number multiplication: at least two-digit by two-digit numbers (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L14$t$, 5, $t$support$t$, $t$remediation$t$, $t$Support: multiply by 10 first$t$, $t$Multiply by 10, then by the ones, and add.$t$, $j${"blocks":[{"type":"steps","items":["Use 12 × 13 as the first example. Multiply 12 by 10: 120.","Multiply 12 by 3: 36.","Add the two parts: 120 + 36 = 156.","Repeat with 14 × 12 using counters or squares on paper."]}]}$j$::jsonb, $t$foundational$t$, 15, array[$t$practical$t$,$t$teacher_led$t$]::text[], false, 1, array[$t$MUL.03$t$,$t$MUL.04$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole-number multiplication: at least two-digit by two-digit numbers (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L14$t$, 6, $t$challenge$t$, $t$extension$t$, $t$Challenge: is it sensible?$t$, $t$Using estimation and structure to check.$t$, $j${"blocks":[{"type":"numbered","items":["Show 27 × 13 in two different ways.","Is 309 a sensible answer for 19 × 21? Estimate and then calculate.","Why is 25 × 16 easy with doubling and halving?"]},{"type":"tip","text":"Answers for the teacher: 1) for example 27 × 10 + 27 × 3 = 351, or with a grid; 2) No. 20 × 20 = 400, and 19 × 21 = 399.; 3) Halve 16 and double 25: 50 × 8, then 100 × 4 = 400."}]}$j$::jsonb, $t$advanced$t$, 15, array[$t$text$t$]::text[], false, 1, array[$t$MUL.03$t$,$t$MUL.04$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole-number multiplication: at least two-digit by two-digit numbers (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L14$t$, 7, $t$check$t$, $t$formative_questions$t$, $t$Questions to ask: Multiplying by a two-digit number$t$, $t$Oral questions that show quickly who understands.$t$, $j${"blocks":[{"type":"numbered","items":["What is 23 × 10?","Estimate 29 × 31.","What is 25 × 4?"]},{"type":"tip","text":"Answers for the teacher: 1) 230; 2) about 900; 3) 100"},{"type":"tip","text":"Ask learners to answer on their fingers, a slate or a scrap of paper so you can see everyone."}]}$j$::jsonb, $t$standard$t$, 5, array[$t$teacher_led$t$]::text[], false, 1, array[$t$MUL.03$t$,$t$MUL.04$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Whole-number multiplication: at least two-digit by two-digit numbers (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L15$t$, 1, $t$explain$t$, $t$teacher_explanation$t$, $t$A routine for money problems$t$, $t$Steps and a worked example.$t$, $j${"blocks":[{"type":"tip","text":"Funda360 example. It is not taken from the DBE documents."},{"type":"steps","items":["Read the problem twice. Underline the question.","Decide what happens: put together (add), take away (subtract), or equal groups (multiply).","Write a number sentence and estimate.","Solve, then check that the answer makes sense.","Write the answer with the unit, for example R52."]},{"type":"paragraph","text":"Worked example: a sandwich costs R12 and a juice costs R8. Thabo buys 3 sandwiches and 2 juices. 3 × 12 + 2 × 8 = 36 + 16 = R52."}]}$j$::jsonb, $t$standard$t$, 10, array[$t$text$t$,$t$teacher_led$t$]::text[], false, 1, array[$t$PS.01$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Problem solving: whole-number problems in financial contexts (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L15$t$, 2, $t$try$t$, $t$group_activity$t$, $t$Class tuckshop$t$, $t$Groups run a pretend shop with price cards and play money.$t$, $j${"blocks":[{"type":"paragraph","text":"Materials: price cards written on paper, and play money made from paper."},{"type":"steps","items":["Make price cards: sandwich R12, juice R8, apple R5.","One learner is the shopper and chooses items. The other adds the cost and gives change from R100.","Write the number sentence for each sale.","Swap roles."]}]}$j$::jsonb, $t$standard$t$, 20, array[$t$practical$t$]::text[], false, 1, array[$t$PS.01$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Problem solving: whole-number problems in financial contexts (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L15$t$, 3, $t$practise$t$, $t$exercise$t$, $t$Practice set: money problems$t$, $t$Six whole-rand problems.$t$, $j${"blocks":[{"type":"numbered","items":["A tuckshop sells a sandwich for R12 and a juice for R8. Thabo buys 3 sandwiches and 2 juices. How much does he pay?","Bheki has R500 and buys shoes for R187. How much money is left?","45 learners each give R15 for a school trip fund. How much money is collected?","A taxi fare is R14 per person. How much do 23 learners pay together?","A school sells 8 books at R35 each and 6 pens at R9 each. What is the total?","Zinhle pays R100 for items that cost R63. How much change does she get?"]},{"type":"tip","text":"Answers for the teacher: 1) R52; 2) R313; 3) R675; 4) R322; 5) R334; 6) R37"}]}$j$::jsonb, $t$standard$t$, 20, array[$t$text$t$]::text[], false, 1, array[$t$PS.01$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Problem solving: whole-number problems in financial contexts (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L15$t$, 4, $t$support$t$, $t$remediation$t$, $t$Support: money problems with small numbers$t$, $t$Use play money and smaller amounts.$t$, $j${"blocks":[{"type":"steps","items":["Use problems with amounts under R50, for example: an apple costs R5, a banana costs R3.","Act out the problem with play money.","Write the number sentence. Say what each number means.","Solve and say the answer in rands."]}]}$j$::jsonb, $t$foundational$t$, 15, array[$t$practical$t$,$t$teacher_led$t$]::text[], false, 1, array[$t$PS.01$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Problem solving: whole-number problems in financial contexts (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L15$t$, 5, $t$challenge$t$, $t$extension$t$, $t$Challenge: which is the better buy?$t$, $t$Reasoning with totals.$t$, $j${"blocks":[{"type":"numbered","items":["Mpho needs 12 pencils. Shop A sells packs of 4 for R20 and Shop B sells packs of 6 for R27. Which shop is cheaper for 12 pencils, and by how much?","Write a money problem that matches 3 × R25 + R40, then solve it."]},{"type":"tip","text":"Answers for the teacher: 1) A: 3 packs = R60. B: 2 packs = R54. Shop B is cheaper by R6.; 2) for example three T-shirts at R25 and a cap at R40: R115."}]}$j$::jsonb, $t$advanced$t$, 15, array[$t$text$t$]::text[], false, 1, array[$t$PS.01$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Problem solving: whole-number problems in financial contexts (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L15$t$, 6, $t$check$t$, $t$formative_questions$t$, $t$Questions to ask: Money problems with whole numbers$t$, $t$Oral questions that show quickly who understands.$t$, $j${"blocks":[{"type":"numbered","items":["An apple costs R5. What do 6 apples cost?","You pay R50 for R32. What is the change?","Which operation finds the total of 4 equal prices?"]},{"type":"tip","text":"Answers for the teacher: 1) R30; 2) R18; 3) multiplication"},{"type":"tip","text":"Ask learners to answer on their fingers, a slate or a scrap of paper so you can see everyone."}]}$j$::jsonb, $t$standard$t$, 5, array[$t$teacher_led$t$]::text[], false, 1, array[$t$PS.01$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Problem solving: whole-number problems in financial contexts (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L16$t$, 1, $t$explain$t$, $t$teacher_explanation$t$, $t$A routine for measurement problems$t$, $t$Units and operations in problems.$t$, $j${"blocks":[{"type":"tip","text":"Funda360 example. It is not taken from the DBE documents."},{"type":"steps","items":["Read the problem and underline the question and the unit (cm, m, kg, ℓ or minutes).","Decide which operation fits the story.","Write a number sentence, estimate and solve.","Check the answer is sensible and write the unit."]},{"type":"paragraph","text":"Worked example: a rope is 250 cm long. Three pieces of 75 cm are cut off. 3 × 75 = 225 cm. 250 − 225 = 25 cm are left."}]}$j$::jsonb, $t$standard$t$, 10, array[$t$text$t$,$t$teacher_led$t$]::text[], false, 1, array[$t$PS.02$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Problem solving: whole-number problems in measurement contexts (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L16$t$, 2, $t$try$t$, $t$classroom_activity$t$, $t$Measure it$t$, $t$Learners measure real objects and make up a problem.$t$, $j${"blocks":[{"type":"paragraph","text":"Materials: a ruler or a measuring tape, a rope or string, a few classroom objects."},{"type":"steps","items":["Measure the length of the desk and of the board in centimetres.","Write a problem that uses both lengths and a whole-number operation.","Swap with another group and solve."]}]}$j$::jsonb, $t$standard$t$, 20, array[$t$practical$t$]::text[], false, 1, array[$t$PS.02$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Problem solving: whole-number problems in measurement contexts (item-level page and week NOT verified)$t$);
  perform pg_temp.add_resource($t$L16$t$, 3, $t$practise$t$, $t$exercise$t$, $t$Practice set: measurement problems$t$, $t$Six whole-number problems.$t$, $j${"blocks":[{"type":"numbered","items":["A rope is 250 cm long. Three pieces of 75 cm are cut off. How much rope is left?","A shop has 15 bags of maize meal. Each bag has a mass of 12 kg. What is the total mass?","Each of 36 learners drinks 2 ℓ of water in a week at school. How many litres do they drink altogether?","Netball practice is 45 minutes, 3 times a week, for 4 weeks. How many minutes is that altogether?","A road is 1 250 m long. Sina walks it twice a day. How far does she walk in a day?","A container holds 5 000 ml. 8 cups of 250 ml are poured out. How much is left?"]},{"type":"tip","text":"Answers for the teacher: 1) 25 cm; 2) 180 kg; 3) 72 ℓ; 4) 540 minutes; 5) 2 500 m; 6) 3 000 ml"}]}$j$::jsonb, $t$standard$t$, 20, array[$t$text$t$]::text[], false, 1, array[$t$PS.02$t$]::text[], $t$2026 Grade 4 Mathematics ATP, Term 1, Problem solving: whole-number problems in measurement contexts (item-level page and week NOT verified)$t$);
