  -- 6. Mark the earlier draft as superseded. Only while it is still a draft: an approved, published or retired
  --    version is never touched. Nothing is deleted, so its Common Fractions topic and every other row stay recoverable.
  update public.curriculum_versions
     set name = case when name like '%SUPERSEDED DRAFT%' then name else name || ' [SUPERSEDED DRAFT: not the 2026 ATP Term 1 scope]' end,
         license_notes = case when license_notes like 'SUPERSEDED DRAFT%' then license_notes
                              else 'SUPERSEDED DRAFT. Kept for history. It is incomplete against the 2026 ATP and places Common Fractions in Term 1, which the 2026 ATP does not. Replaced by ZA-G4-MATH-2026-T1 (also a draft). ' || coalesce(license_notes, '') end
   where code = 'ZA-CAPS-G4-MATH-SLICE' and status = 'draft';

  raise notice 'content pack ZA-G4-MATH-2026-T1 loaded as DRAFT, NOT VERIFIED (version %)', v_version;
end
